        case NpcAction::Arrest: {
            faceToward(playerPos);
            if (dist > kCatchRadius) {
                const Vec3 step = normalize(playerPos - position_) * (kNpcRun * dt);
                position_ = city.resolveMovement(position_, position_ + step, kNpcRadius);
