        case NpcAction::Stop:
        case NpcAction::Face:
            faceToward(playerPos);
            break;
        case NpcAction::None:
        case NpcAction::RaiseHand:  // gesture-only kinds never reach behavior_
        case NpcAction::Wave:
            break;
    }
