13	namespace llm_npc_test {
14	
15	// In-process stand-in for Ollama's /api/chat endpoint. Listens on a random
16	// localhost port and serves canned NDJSON streams so LlmClient's protocol
17	// handling can be tested offline, including error paths and chunk framing
18	// that splits JSON lines across TCP packets.
19	class FakeOllama {
20	   public:
21	    enum class Mode {
22	        StreamWords,      // stream replyText word by word, then done:true
23	        Http500,          // non-200 status with a JSON error body
24	        ErrorLine,        // 200, but the stream carries an {"error": ...} line
25	        TruncatedStream,  // 200, deltas arrive but done:true never does
26	    };
27	
28	    FakeOllama() {
29	        server_.Post("/api/chat", [this](const httplib::Request& req, httplib::Response& res) {
30	            {
31	                std::lock_guard<std::mutex> lock(mutex_);
32	                requestBodies_.push_back(req.body);
33	            }
34	            if (mode_ == Mode::Http500) {
35	                res.status = 500;
36	                res.set_content("{\"error\":\"server exploded\"}", "application/json");
37	                return;
38	            }
39	            respondStreaming(res);
40	        });
41	        port_ = server_.bind_to_any_port("127.0.0.1");
42	        thread_ = std::thread([this] { server_.listen_after_bind(); });
43	        server_.wait_until_ready();
44	    }
45	
46	    ~FakeOllama() {
47	        server_.stop();
48	        if (thread_.joinable()) thread_.join();
49	    }
50	
51	    FakeOllama(const FakeOllama&) = delete;
52	    FakeOllama& operator=(const FakeOllama&) = delete;
53	
54	    // The localhost port the fake is listening on.
55	    int port() const { return port_; }
56	
57	    // Selects the canned behavior for subsequent requests.
58	    void setMode(Mode mode) { mode_ = mode; }
59	
60	    // The assistant text streamed in StreamWords mode.
61	    void setReply(std::string text) {
62	        std::lock_guard<std::mutex> lock(mutex_);
63	        replyText_ = std::move(text);
64	    }
65	
66	    // Raw JSON bodies of every request received so far.
67	    std::vector<std::string> requestBodies() {
68	        std::lock_guard<std::mutex> lock(mutex_);
69	        return requestBodies_;
70	    }
71	
72	   private:
73	    // Builds the NDJSON payload for the current mode and serves it in small
74	    // fixed-size chunks so lines straddle receive callbacks on the client.
75	    void respondStreaming(httplib::Response& res) {
76	        std::string payload;
77	        {
78	            std::lock_guard<std::mutex> lock(mutex_);
79	            if (mode_ == Mode::ErrorLine) {
80	                payload = "{\"error\":\"model not found\"}\n";
81	            } else {
82	                std::string word;
83	                std::vector<std::string> words;
84	                for (char c : replyText_) {
85	                    word.push_back(c);
86	                    if (c == ' ') {
87	                        words.push_back(word);
88	                        word.clear();
89	                    }
90	                }
91	                if (!word.empty()) words.push_back(word);
92	                for (const auto& w : words) {
93	                    nlohmann::json line = {{"message", {{"role", "assistant"}, {"content", w}}},
94	                                           {"done", false}};
