+void Npc::applyAction(NpcAction action) {
+    switch (action) {
+        case NpcAction::None:
+            // The reply carried no directive; leave existing behavior intact.
+            break;
+        case NpcAction::Follow:
+        case NpcAction::Stop:
+        case NpcAction::Face:
+        case NpcAction::Arrest:
+            behavior_ = action;
+            caughtPlayer_ = false;  // a new instruction clears the latch
