    CHECK(distanceXZ(cop.position(), Vec3{4.f, 0.f, -36.f}) < 1.f);
    CHECK(cop.behavior() == NpcAction::None);
    CHECK(cop.facingDeg() == doctest::Approx(90.f));  // spawn facing restored
}

