// Exercises the full new pipeline headlessly: real persona prompts (police
// flag, mood protocol, emotes) + real Ollama + the game's parseDirectives.
#include <chrono>
#include <iostream>
#include <string>
#include <thread>

#include "LlmClient.hpp"
#include "Npc.hpp"
#include "PersonaLoader.hpp"

using namespace llm_npc;

static const char* an(NpcAction a) {
    switch (a) {
        case NpcAction::None: return "None";
        case NpcAction::Follow: return "Follow";
        case NpcAction::Stop: return "Stop";
        case NpcAction::Face: return "Face";
        case NpcAction::RaiseHand: return "RaiseHand";
        case NpcAction::Wave: return "Wave";
        case NpcAction::Arrest: return "Arrest";
        case NpcAction::CallPolice: return "CallPolice";
        case NpcAction::ReturnHome: return "ReturnHome";
    }
    return "?";
}
static const char* mn(NpcMood m) {
    switch (m) {
        case NpcMood::Neutral: return "Neutral";
        case NpcMood::Happy: return "Happy";
        case NpcMood::Angry: return "Angry";
        case NpcMood::Sad: return "Sad";
        case NpcMood::Embarrassed: return "Embarrassed";
        case NpcMood::Surprised: return "Surprised";
    }
    return "?";
}

static void run(const LoadedPersona& lp, LlmClient& client, const std::string& line) {
    Npc npc(lp.persona, client);
    const auto id = npc.ask(line);
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(40);
    while (std::chrono::steady_clock::now() < deadline) {
        for (const auto& r : client.drainReplies()) {
            if (r.id != id) continue;
            const auto text = npc.onReplyArrived(r);
            std::cout << "[" << lp.id << "] \"" << line << "\"\n   reply: "
                      << text.value_or("<err>") << "\n   action=" << an(npc.lastAction())
                      << " mood=" << mn(npc.mood()) << "\n\n";
            return;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
    std::cout << "[" << lp.id << "] TIMEOUT\n\n";
}

int main() {
    auto personas = loadAllPersonas("personas", nullptr);
    const LoadedPersona *cop = nullptr, *baker = nullptr;
    for (const auto& p : personas) {
        if (p.id == "cop") cop = &p;
        if (p.id == "baker") baker = &p;
    }
    if (!cop || !baker) { std::cerr << "personas not found\n"; return 1; }
    LlmClient client({});
    run(*baker, client, "I love you.");
    run(*baker, client, "you suck");
    run(*baker, client, "I like your hat!");
    run(*baker, client, "*shouts loudly in your face* GIVE ME FREE BREAD!");
    run(*cop, client, "I stole a hot dog. Arrest me if you can!");
    return 0;
}
