    {{sf::Color(60, 120, 170), sf::Color(190, 150, 100)}},   // musician: denim + guitar wood
    {{sf::Color(200, 50, 50), sf::Color(250, 245, 235)}},    // hot dog: red + white stripes
    {{sf::Color(160, 90, 40), sf::Color(110, 110, 120)}},    // hardware: work tan + steel
