1	#pragma once
2	
3	#include <cctype>
4	#include <string>
5	
6	namespace llm_npc {
7	
8	// A physical action an NPC can take in the world, decided by the LLM in
9	// response to a player instruction ("follow me", "wave", ...). The model emits
10	// action tags in its replies; parseDirectives() turns them into one of these.
11	// Three kinds are mixed here: persistent movement behaviors (Follow, Arrest,
12	// Stop, Face, ReturnHome), transient gesture poses (RaiseHand, Wave), and the
13	// world-level CallPolice signal. The Npc routes each kind to the right state.
14	enum class NpcAction {
15	    None,
16	    Follow,      // trail the player at a walk until told otherwise
17	    Stop,        // hold position, face the player
18	    Face,        // turn to look at the player, don't move
19	    RaiseHand,   // raise the right hand for a few seconds
20	    Wave,        // wave the right hand for a few seconds
21	    Arrest,      // police only: chase the player down, then stop on catch
22	    CallPolice,  // civilians: summon the police to come arrest the player
23	    ReturnHome,  // not LLM-emittable: walk back to the spawn spot
24	};
25	
26	// The NPC's emotional read on the conversation, also emitted by the LLM as a
27	// tag on every reply. Drives the rendered facial expression.
28	enum class NpcMood {
29	    Neutral,
30	    Happy,
31	    Angry,
32	    Sad,
33	    Embarrassed,
34	    Surprised,
35	};
36	
37	// Everything extracted from one reply's directive tags.
38	struct Directives {
39	    NpcAction action = NpcAction::None;
40	    NpcMood mood = NpcMood::Neutral;
41	    bool hasMood = false;  // distinguishes "said neutral" from "said nothing"
42	};
43	
44	// Maps a normalized (lowercase, '_'-joined) tag keyword to its action.
45	// Unknown keywords yield None. ReturnHome is internal and not mapped.
46	inline NpcAction actionFromKeyword(const std::string& kw) {
47	    if (kw == "follow") return NpcAction::Follow;
48	    if (kw == "stop" || kw == "stay") return NpcAction::Stop;
49	    if (kw == "face" || kw == "look") return NpcAction::Face;
50	    if (kw == "raise_hand" || kw == "raise") return NpcAction::RaiseHand;
51	    if (kw == "wave") return NpcAction::Wave;
52	    if (kw == "arrest") return NpcAction::Arrest;
53	    if (kw == "call_police" || kw == "police") return NpcAction::CallPolice;
54	    return NpcAction::None;
55	}
56	
57	// Maps a normalized mood keyword to a mood, with synonyms for the words small
58	// models actually emit. Unknown keywords yield Neutral with `ok = false`.
59	inline bool moodFromKeyword(const std::string& kw, NpcMood& out) {
60	    if (kw == "neutral" || kw == "calm") out = NpcMood::Neutral;
61	    else if (kw == "happy" || kw == "flattered" || kw == "pleased" ||
62	             kw == "excited" || kw == "joyful" || kw == "amused") out = NpcMood::Happy;
63	    else if (kw == "angry" || kw == "annoyed" || kw == "irritated" ||
64	             kw == "frustrated" || kw == "mad") out = NpcMood::Angry;
65	    else if (kw == "sad" || kw == "upset" || kw == "hurt" ||
66	             kw == "disappointed") out = NpcMood::Sad;
67	    else if (kw == "embarrassed" || kw == "flustered" || kw == "awkward" ||
68	             kw == "shy" || kw == "nervous") out = NpcMood::Embarrassed;
69	    else if (kw == "surprised" || kw == "shocked" || kw == "startled") out = NpcMood::Surprised;
70	    else return false;
71	    return true;
72	}
73	
74	// Lowercase copy of s (ASCII), used for case-insensitive matching.
75	inline std::string toLowerAscii(const std::string& s) {
76	    std::string out = s;
77	    for (char& c : out) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
78	    return out;
79	}
80	
81	// Extracts every directive tag from an LLM reply, tolerating the mess a small
82	// model actually produces: tags at the start, middle, or end; doubled or
83	// single brackets; duplicate mood tags (the last one wins); unknown keywords.
84	// All recognized-looking tags ("action"/"mood" kinds) are erased from `reply`
85	// in place - including unknown keywords, so brackets never reach the
86	// transcript - and seam whitespace is collapsed. Other bracketed text (e.g.
87	// "[sigh]" or "[[1]]") is left alone.
88	inline Directives parseDirectives(std::string& reply) {
89	    Directives out;
90	
91	    std::size_t i = 0;
92	    while (i < reply.size()) {
93	        if (reply[i] != '[') {
94	            ++i;
95	            continue;
96	        }
97	        const std::size_t open = i;
98	        std::size_t inner = open + 1;
99	        if (inner < reply.size() && reply[inner] == '[') ++inner;  // "[[" form
100	        const std::size_t close = reply.find(']', inner);
101	        if (close == std::string::npos) break;  // no closing bracket anywhere
102	        std::size_t end = close + 1;
103	        // Consume a second ']' if present so "]]" closes fully.
104	        if (end < reply.size() && reply[end] == ']') ++end;
105	
106	        // "kind : keyword" between the brackets.
107	        const std::string body = toLowerAscii(reply.substr(inner, close - inner));
108	        const std::size_t colon = body.find(':');
109	        if (colon == std::string::npos) {
110	            ++i;
111	            continue;
112	        }
113	        const auto trimRange = [&](std::size_t b, std::size_t e) {
114	            while (b < e && std::isspace(static_cast<unsigned char>(body[b]))) ++b;
115	            while (e > b && std::isspace(static_cast<unsigned char>(body[e - 1]))) --e;
116	            return body.substr(b, e - b);
117	        };
118	        const std::string kind = trimRange(0, colon);
119	        std::string keyword = trimRange(colon + 1, body.size());
120	        // Normalize inner spaces to underscores ("call police" -> "call_police").
121	        for (char& c : keyword) {
122	            if (std::isspace(static_cast<unsigned char>(c))) c = '_';
123	        }
124	
125	        if (kind != "action" && kind != "mood") {
126	            ++i;
127	            continue;
128	        }
129	
130	        if (kind == "action") {
131	            const NpcAction action = actionFromKeyword(keyword);
132	            if (action != NpcAction::None) out.action = action;
133	        } else {
134	            NpcMood mood = NpcMood::Neutral;
135	            if (moodFromKeyword(keyword, mood)) {
136	                out.mood = mood;  // last recognized mood wins
137	                out.hasMood = true;
138	            }
139	        }
140	
141	        // Strip the tag and collapse the whitespace seam it leaves behind.
142	        reply.erase(open, end - open);
143	        while (open < reply.size() && open > 0 &&
144	               std::isspace(static_cast<unsigned char>(reply[open])) &&
