1	#include "Npc.hpp"
2	
3	#include <cmath>
4	#include <utility>
5	
6	namespace llm_npc {
7	
8	namespace {
9	// Movement tuning, in world units (~meters). NPCs are deliberately a touch
10	// slower than the player (kWalkSpeed = 7 in main.cpp) so following feels like
11	// trailing rather than shoving, while an arrest can nearly keep pace.
12	constexpr float kNpcWalk = 3.8f;       // follow speed
13	constexpr float kNpcRun = 6.0f;        // arrest speed
14	constexpr float kNpcRadius = 0.45f;    // collision circle, matches the player
15	constexpr float kFollowStop = 2.5f;    // stop this close when following
16	constexpr float kCatchRadius = 1.6f;   // arrest succeeds within this range
17	// Long enough that the gesture is still playing after the player reads the
18	// reply and leaves the dialog to look at the NPC (the timer starts the moment
19	// the reply lands, while the dialog may still be open).
20	constexpr float kGestureSeconds = 15.f; // how long raise_hand / wave holds
21	constexpr float kMoodSeconds = 25.f;    // how long an expression lingers
22	constexpr float kHomeSnapRadius = 0.6f; // close enough to be "back at post"
23	}  // namespace
24	
25	Npc::Npc(Persona persona, LlmClient& client, int maxHistoryTurns)
26	    : persona_(std::move(persona)), client_(client), maxHistoryTurns_(maxHistoryTurns) {}
27	
28	std::uint64_t Npc::ask(const std::string& playerLine) {
29	    // Send a snapshot of the current history; the player line is appended to
30	    // history only once a successful reply arrives. That way a failed request
31	    // can be retried without polluting context with unanswered user turns.
32	    pendingUserLine_ = playerLine;
33	    pendingId_ = client_.submit(persona_.renderSystemPrompt(), history_, playerLine);
34	    return pendingId_;
35	}
36	
37	std::optional<std::string> Npc::onReplyArrived(const ChatReply& reply) {
38	    if (reply.id != pendingId_) return std::nullopt;
39	    pendingId_ = 0;
40	
41	    if (!reply.ok) {
42	        // Don't append anything on failure — let the UI report the error and
43	        // let the player retry. Clear the pending user line too.
44	        pendingUserLine_.clear();
45	        return std::nullopt;
46	    }
47	
48	    // Pull every directive tag out of the reply before it is shown or
49	    // remembered, so tags never appear in the transcript or future context,
50	    // and route them into behavior/gesture/mood state.
51	    std::string content = reply.content;
52	    const Directives directives = parseDirectives(content);
53	    applyAction(directives.action);
54	    if (directives.hasMood) {
55	        mood_ = directives.mood;
56	        moodTimer_ = kMoodSeconds;
57	    }
58	
59	    history_.push_back({"user", std::move(pendingUserLine_)});
60	    history_.push_back({"assistant", content});
61	    pendingUserLine_.clear();
62	    trimHistory();
63	    return content;
64	}
65	
66	void Npc::applyAction(NpcAction action) {
67	    // Only police can actually arrest; when the model has a civilian try
68	    // anyway, treat it as calling for the police instead.
69	    if (action == NpcAction::Arrest && !persona_.police) action = NpcAction::CallPolice;
70	
71	    lastAction_ = action;  // remembered for one turn so the UI can narrate it
72	    switch (action) {
73	        case NpcAction::None:
74	        case NpcAction::ReturnHome:  // internal-only; never arrives from a reply
75	            // Leave existing behavior intact.
76	            break;
77	        case NpcAction::Follow:
78	        case NpcAction::Stop:
79	        case NpcAction::Face:
80	        case NpcAction::Arrest:
81	            behavior_ = action;
82	            caughtPlayer_ = false;  // a new instruction clears the latch
83	            break;
84	        case NpcAction::CallPolice:
85	            // The world (main loop) routes the summons to police NPCs; the
86	            // caller just flags someone down, which reads as a wave.
87	            pose_ = NpcAction::Wave;
88	            poseTimer_ = kGestureSeconds;
89	            gesturePhase_ = 0.f;
90	            break;
91	        case NpcAction::RaiseHand:
92	        case NpcAction::Wave:
93	            pose_ = action;
94	            poseTimer_ = kGestureSeconds;
95	            gesturePhase_ = 0.f;
96	            break;
97	    }
98	}
99	
100	void Npc::faceToward(const Vec3& target) {
101	    const float dx = target.x - position_.x;
102	    const float dz = target.z - position_.z;
103	    if (dx * dx + dz * dz < 1e-6f) return;  // on top of target; keep facing
104	    // Yaw convention matches flatForward/forwardFromAngles: 0 looks toward +Z,
105	    // increasing toward +X, hence atan2(dx, dz).
106	    facingDeg_ = std::atan2(dx, dz) * 180.f / 3.14159265358979323846f;
107	}
108	
109	void Npc::update(float dt, const Vec3& playerPos, const City& city) {
110	    // Tick down any gesture overlay independently of movement.
111	    if (poseTimer_ > 0.f) {
112	        gesturePhase_ += dt;
113	        poseTimer_ -= dt;
114	        if (poseTimer_ <= 0.f) {
115	            pose_ = NpcAction::None;
116	            poseTimer_ = 0.f;
117	        }
118	    }
119	
120	    // Expressions relax back to neutral when the conversation moves on.
121	    if (moodTimer_ > 0.f) {
122	        moodTimer_ -= dt;
123	        if (moodTimer_ <= 0.f) {
124	            mood_ = NpcMood::Neutral;
125	            moodTimer_ = 0.f;
126	        }
127	    }
128	
129	    const float dist = distanceXZ(position_, playerPos);
130	
131	    switch (behavior_) {
132	        case NpcAction::Follow: {
133	            faceToward(playerPos);
134	            if (dist > kFollowStop) {
135	                const Vec3 step = normalize(playerPos - position_) * (kNpcWalk * dt);
136	                position_ = city.resolveMovement(position_, position_ + step, kNpcRadius);
137	            }
138	            break;
139	        }
140	        case NpcAction::Arrest: {
141	            faceToward(playerPos);
142	            if (dist > kCatchRadius) {
143	                const Vec3 step = normalize(playerPos - position_) * (kNpcRun * dt);
144	                position_ = city.resolveMovement(position_, position_ + step, kNpcRadius);
145	            } else {
146	                behavior_ = NpcAction::Stop;  // caught: settle and hold
147	                caughtPlayer_ = true;
148	            }
149	            break;
150	        }
151	        case NpcAction::ReturnHome: {
152	            const float homeDist = distanceXZ(position_, homePosition_);
153	            if (homeDist > kHomeSnapRadius) {
154	                faceToward(homePosition_);
