9	namespace llm_npc {
10	
11	namespace {
12	
13	// Split a comma-separated list into trimmed, non-empty items.
14	std::vector<std::string> splitCsv(const std::string& s) {
15	    std::vector<std::string> out;
16	    std::string item;
17	    std::istringstream in(s);
18	    while (std::getline(in, item, ',')) {
19	        item = trim(item);
20	        if (!item.empty()) out.push_back(item);
21	    }
22	    return out;
23	}
24	
25	// Parse "x, z" into a ground-plane position. Returns false on bad input.
26	bool parsePosition(const std::string& s, Vec3& out) {
27	    auto parts = splitCsv(s);
28	    if (parts.size() != 2) return false;
29	    try {
30	        out.x = std::stof(parts[0]);
31	        out.z = std::stof(parts[1]);
32	        out.y = 0.f;
33	    } catch (const std::exception&) {
34	        return false;
35	    }
36	    return true;
37	}
38	
39	}  // namespace
40	
41	PersonaParseResult parsePersonaText(const std::string& text, const std::string& id) {
42	    PersonaParseResult result;
43	    result.value.id = id;
44	
45	    std::istringstream in(text);
46	    std::string line;
47	    std::ostringstream extra;
48	    bool inExtra = false;
49	
50	    while (std::getline(in, line)) {
51	        if (!inExtra) {
52	            const std::string t = trim(line);
53	            if (t == "---") {
54	                inExtra = true;
55	                continue;
56	            }
57	            if (t.empty()) continue;
58	            const auto eq = t.find('=');
59	            if (eq == std::string::npos) {
60	                result.error = id + ": header line without '=': " + t;
61	                return result;
62	            }
63	            const std::string key = trim(t.substr(0, eq));
64	            const std::string val = trim(t.substr(eq + 1));
65	            if (key == "name") {
66	                result.value.persona.name = val;
67	            } else if (key == "role") {
68	                result.value.persona.role = val;
69	            } else if (key == "traits") {
70	                result.value.persona.traits = splitCsv(val);
71	            } else if (key == "style") {
72	                result.value.persona.speakingStyle = val;
73	            } else if (key == "knowledge") {
74	                result.value.persona.knowledgeBoundary = val;
75	            } else if (key == "spot") {
76	                result.value.spotId = val;
77	            } else if (key == "position") {
78	                if (!parsePosition(val, result.value.position)) {
79	                    result.error = id + ": bad position '" + val + "' (want: x, z)";
80	                    return result;
81	                }
82	            } else if (key == "facing") {
83	                try {
84	                    result.value.facingDeg = std::stof(val);
85	                } catch (const std::exception&) {
86	                    result.error = id + ": bad facing '" + val + "'";
87	                    return result;
88	                }
89	            } else if (key == "police") {
90	                // Grants the arrest action; everyone else can only summon
91	                // the police. Accepts true/yes/1 (anything else is false).
92	                result.value.persona.police = (val == "true" || val == "yes" || val == "1");
93	            } else {
94	                result.error = id + ": unknown header key '" + key + "'";
95	                return result;
96	            }
97	        } else {
98	            extra << line << '\n';
99	        }
100	    }
101	
102	    if (result.value.persona.name.empty()) {
103	        result.error = id + ": missing required 'name'";
104	        return result;
105	    }
106	    result.value.persona.extraDirectives = trim(extra.str());
107	    result.ok = true;
108	    return result;
109	}
110	
111	PersonaParseResult parsePersonaFile(const std::filesystem::path& path) {
112	    const std::string id = path.stem().string();
113	    std::ifstream in(path);
114	    if (!in) {
115	        PersonaParseResult result;
116	        result.error = id + ": cannot open " + path.string();
117	        return result;
118	    }
119	    std::ostringstream buf;
120	    buf << in.rdbuf();
121	    return parsePersonaText(buf.str(), id);
122	}
123	
124	std::vector<LoadedPersona> loadAllPersonas(const std::filesystem::path& dir,
125	                                           std::vector<std::string>* errors) {
126	    std::vector<std::filesystem::path> files;
127	    std::error_code ec;
128	    for (const auto& entry : std::filesystem::directory_iterator(dir, ec)) {
129	        if (entry.is_regular_file() && entry.path().extension() == ".persona") {
130	            files.push_back(entry.path());
131	        }
132	    }
133	    std::sort(files.begin(), files.end());
134	
135	    std::vector<LoadedPersona> out;
136	    for (const auto& f : files) {
137	        PersonaParseResult r = parsePersonaFile(f);
138	        if (r.ok) {
139	            out.push_back(std::move(r.value));
140	        } else if (errors) {
141	            errors->push_back(r.error);
142	        }
143	    }
144	    return out;
145	}
146	
147	}  // namespace llm_npc
