747	void Renderer3D::drawNpc(const NpcVisual& npc) {
748	    const auto& palette = kNpcPalettes[static_cast<std::size_t>(npc.palette) % kNpcPalettes.size()];
749	    const sf::Color body = palette[0];
750	    const sf::Color accent = palette[1];
751	    const sf::Color skin(235, 200, 175);
752	
753	    glPushMatrix();
754	    glTranslatef(npc.position.x, npc.position.y, npc.position.z);
755	    // +facing about Y maps the figure's local +Z (visor/front) onto
756	    // flatForward(facing); negating it mirrored every NPC in X.
757	    glRotatef(npc.facingDeg, 0.0f, 1.0f, 0.0f);
758	
759	    // A soft contact shadow grounds the figure.
760	    drawBlobShadow(0.5f);
761	
762	    // Rounded, smooth-shaded figure: two tapered legs, hips, a torso that
763	    // flares to the shoulders, a neck, a spherical head, and a hair cap.
764	    drawTaperedCylinder(Vec3{-0.13f, 0.45f, 0.f}, 0.11f, 0.16f, 0.45f, 12, texCloth_, accent);
765	    drawTaperedCylinder(Vec3{0.13f, 0.45f, 0.f}, 0.11f, 0.16f, 0.45f, 12, texCloth_, accent);
766	    drawSphere(Vec3{0.f, 0.92f, 0.f}, 0.27f, 14, 10, texCloth_, body);
767	    drawTaperedCylinder(Vec3{0.f, 1.2f, 0.f}, 0.24f, 0.33f, 0.30f, 16, texCloth_, body);
768	    drawSphere(Vec3{-0.30f, 1.46f, 0.f}, 0.13f, 10, 8, texCloth_, body);
769	    drawSphere(Vec3{0.30f, 1.46f, 0.f}, 0.13f, 10, 8, texCloth_, body);
770	    drawTexturedCylinder(Vec3{0.f, 1.55f, 0.f}, 0.09f, 0.07f, 10, texCloth_, skin);
771	    drawSphere(Vec3{0.f, 1.70f, 0.f}, 0.18f, 16, 12, texCloth_, skin);
772	    drawFace(npc.face);
773	    // Hair cap: a flattened sphere skull-cap on the crown, tilted back so it
774	    // never covers the face.
775	    glPushMatrix();
776	    glTranslatef(0.f, 1.78f, -0.02f);
777	    glScalef(1.0f, 0.55f, 1.0f);
778	    drawSphere(Vec3{0.f, 0.f, 0.f}, 0.18f, 14, 8, texCloth_, accent);
779	    glPopMatrix();
780	
781	    // Arms hang at the sides by default. The NPC's right arm (+X local) can be
782	    // raised or waved in response to a "raise your hand" / "wave" instruction;
783	    // the left arm always hangs.
784	    drawArm(-0.34f, body, skin, 0.f, 0.f);  // left, always down
785	    float raise = 0.f;   // degrees about local +X: 0 = down, ~195 = up & forward
786	    float swing = 0.f;   // degrees about local +Z for a side-to-side wave
787	    if (npc.pose == NpcPose::RaiseHand) {
788	        raise = 195.f;
789	    } else if (npc.pose == NpcPose::Wave) {
790	        raise = 195.f;
791	        swing = 22.f * std::sin(npc.gesturePhase * 9.f);
792	    }
793	    drawArm(0.34f, body, skin, raise, swing);  // right, posed
794	
795	    glPopMatrix();
796	}
797	
798	// Draws the facial features on the head's front (+Z) face in the NPC's local
799	// frame. Everything is tiny textured boxes sitting just proud of the skin so
800	// they read at a distance: dark eyes and brows, a mouth whose corners shift
801	// with the expression, blush patches when embarrassed, wide eyes and an open
802	// mouth when surprised, slanted brows when angry or sad.
803	void Renderer3D::drawFace(NpcFace face) const {
804	    const sf::Color dark(45, 38, 38);
805	    const sf::Color lip(150, 75, 70);
806	    const sf::Color blush(235, 140, 150);
807	    const float zFront = 0.176f;  // head half-depth 0.17 + a hair
808	
809	    // Eyes: taller when surprised.
810	    const float eyeHalfY = face == NpcFace::Surprised ? 0.040f : 0.022f;
811	    drawTexturedBox(Vec3{-0.07f, 1.71f, zFront}, 0.024f, eyeHalfY, 0.006f, texCloth_, dark, 1.f);
812	    drawTexturedBox(Vec3{0.07f, 1.71f, zFront}, 0.024f, eyeHalfY, 0.006f, texCloth_, dark, 1.f);
813	
814	    // Brows: flat by default, inner ends pulled down when angry, up when sad,
815	    // raised high when surprised. With the mirrored per-side rotation below,
816	    // a positive tilt lowers the inner (nose-side) ends: +theta about Z lifts
817	    // a box's +X end, and each side's inner end alternates between +X and -X.
818	    float browTilt = 0.f;  // degrees about local +Z, applied mirrored per side
819	    if (face == NpcFace::Angry) browTilt = 18.f;
820	    if (face == NpcFace::Sad) browTilt = -14.f;
821	    const float browY = face == NpcFace::Surprised ? 1.80f : 1.77f;
822	    for (int side = -1; side <= 1; side += 2) {
823	        glPushMatrix();
824	        glTranslatef(0.07f * static_cast<float>(side), browY, 0.f);
825	        glRotatef(browTilt * static_cast<float>(side), 0.f, 0.f, 1.f);
826	        drawTexturedBox(Vec3{0.f, 0.f, zFront}, 0.038f, 0.008f, 0.006f, texCloth_, dark, 1.f);
827	        glPopMatrix();
828	    }
829	
830	    // Mouth.
831	    switch (face) {
832	        case NpcFace::Surprised:
833	            // Small open "o".
834	            drawTexturedBox(Vec3{0.f, 1.615f, zFront}, 0.022f, 0.030f, 0.006f, texCloth_, dark, 1.f);
835	            break;
836	        case NpcFace::Happy:
837	            drawTexturedBox(Vec3{0.f, 1.615f, zFront}, 0.045f, 0.008f, 0.006f, texCloth_, lip, 1.f);
838	            drawTexturedBox(Vec3{-0.048f, 1.628f, zFront}, 0.010f, 0.010f, 0.006f, texCloth_, lip, 1.f);
839	            drawTexturedBox(Vec3{0.048f, 1.628f, zFront}, 0.010f, 0.010f, 0.006f, texCloth_, lip, 1.f);
840	            break;
841	        case NpcFace::Sad:
842	        case NpcFace::Angry:
843	            drawTexturedBox(Vec3{0.f, 1.612f, zFront}, 0.040f, 0.008f, 0.006f, texCloth_, lip, 1.f);
844	            drawTexturedBox(Vec3{-0.044f, 1.600f, zFront}, 0.010f, 0.010f, 0.006f, texCloth_, lip, 1.f);
845	            drawTexturedBox(Vec3{0.044f, 1.600f, zFront}, 0.010f, 0.010f, 0.006f, texCloth_, lip, 1.f);
846	            break;
847	        case NpcFace::Embarrassed:
848	            // Tight little mouth plus blush patches on the cheeks.
849	            drawTexturedBox(Vec3{0.f, 1.612f, zFront}, 0.022f, 0.008f, 0.006f, texCloth_, lip, 1.f);
850	            drawTexturedBox(Vec3{-0.115f, 1.66f, zFront}, 0.030f, 0.016f, 0.005f, texCloth_, blush, 1.f);
851	            drawTexturedBox(Vec3{0.115f, 1.66f, zFront}, 0.030f, 0.016f, 0.005f, texCloth_, blush, 1.f);
852	            break;
853	        case NpcFace::Neutral:
854	            drawTexturedBox(Vec3{0.f, 1.612f, zFront}, 0.038f, 0.008f, 0.006f, texCloth_, lip, 1.f);
855	            break;
856	    }
857	}
858	
859	// Draws one arm in the NPC's local frame, pivoting at the shoulder. `xOffset`
860	// places it left (-) or right (+); `raiseDeg` rotates it up about local +X
861	// (0 hangs down, ~180 points straight up); `swingDeg` adds a side-to-side
862	// rotation about local +Z for waving. Upper arm is sleeve-colored cloth with a
863	// small skin "hand" at the end.
864	void Renderer3D::drawArm(float xOffset, const sf::Color& sleeve, const sf::Color& skin,
865	                         float raiseDeg, float swingDeg) const {
866	    const float shoulderY = 1.46f;
867	    const float armHalf = 0.27f;  // half-length of the upper arm
868	    glPushMatrix();
869	    glTranslatef(xOffset, shoulderY, 0.f);
870	    if (swingDeg != 0.f) glRotatef(swingDeg, 0.f, 0.f, 1.f);
871	    if (raiseDeg != 0.f) glRotatef(raiseDeg, 1.f, 0.f, 0.f);
872	    // A tapered sleeve and a rounded hand extend downward from the shoulder.
