7	// Squared distance from point (x, z) to the nearest point of footprint a.
8	float distSqToAABB(const AABB& a, float x, float z) {
9	    const float cx = clampf(x, a.minX, a.maxX);
10	    const float cz = clampf(z, a.minZ, a.maxZ);
11	    const float dx = x - cx;
12	    const float dz = z - cz;
13	    return dx * dx + dz * dz;
14	}
