18	std::vector<AABB> buildingWallSegments(const Building& b) {
19	    const float t = kWallThickness;
20	    const float half = kDoorWidth * 0.5f;
21	    const float cx = (b.minX + b.maxX) * 0.5f;
22	    const float cz = (b.minZ + b.maxZ) * 0.5f;
23	    std::vector<AABB> walls;
24	
25	    // West (-X) wall, split when the door is here.
26	    if (b.doorSide == DoorSide::NegX) {
27	        walls.push_back({b.minX, b.minZ, b.minX + t, cz - half});
28	        walls.push_back({b.minX, cz + half, b.minX + t, b.maxZ});
29	    } else {
30	        walls.push_back({b.minX, b.minZ, b.minX + t, b.maxZ});
31	    }
32	    // East (+X) wall.
33	    if (b.doorSide == DoorSide::PosX) {
34	        walls.push_back({b.maxX - t, b.minZ, b.maxX, cz - half});
35	        walls.push_back({b.maxX - t, cz + half, b.maxX, b.maxZ});
36	    } else {
37	        walls.push_back({b.maxX - t, b.minZ, b.maxX, b.maxZ});
38	    }
39	    // South (-Z) wall.
40	    if (b.doorSide == DoorSide::NegZ) {
41	        walls.push_back({b.minX, b.minZ, cx - half, b.minZ + t});
42	        walls.push_back({cx + half, b.minZ, b.maxX, b.minZ + t});
43	    } else {
44	        walls.push_back({b.minX, b.minZ, b.maxX, b.minZ + t});
45	    }
46	    // North (+Z) wall.
47	    if (b.doorSide == DoorSide::PosZ) {
48	        walls.push_back({b.minX, b.maxZ - t, cx - half, b.maxZ});
49	        walls.push_back({cx + half, b.maxZ - t, b.maxX, b.maxZ});
50	    } else {
51	        walls.push_back({b.minX, b.maxZ - t, b.maxX, b.maxZ});
52	    }
53	    return walls;
54	}
