96	// Ground-plane right vector for a yaw in degrees. Must match the camera's
97	// right basis in Renderer3D (cross(forward, up)) or strafe is inverted —
98	// cross((fx,0,fz),(0,1,0)) = (-fz, 0, fx).
99	Vec3 flatRight(float yawDeg) {
