131	// Applies one frame of mouse look from the raw HID movement delta.
132	void handleMouseLook(sf::RenderWindow& window, CameraPose& camera) {
133	    if (!window.hasFocus()) return;
134	    std::int32_t dx = 0, dy = 0;
135	    CGGetLastMouseDelta(&dx, &dy);
136	    // Mouse-right must lower yaw: screen-right is cross(forward, up) = -X at
137	    // yaw 0, but increasing yaw rotates forward toward +X (screen-left).
138	    camera.yawDeg -= static_cast<float>(dx) * kMouseSensitivity;
139	    camera.pitchDeg = clampf(camera.pitchDeg - static_cast<float>(dy) * kMouseSensitivity,
140	                             -kMaxPitchDeg, kMaxPitchDeg);

