              "model = old:tag\n"
              "keep_alive = 10m\n");
    REQUIRE(llm_npc::setKvValue(tmp.path / "llm.cfg", "model", "new:tag"));
    auto kv = llm_npc::readKv(tmp.path / "llm.cfg");
    CHECK(kv["model"] == "new:tag");
