    tmp.write("a.cfg",
              "# full-line comment\n"
              "host = localhost  # trailing comment\n"
              "\n"
              "port=11434\n"
              "broken line without equals\n");
    auto kv = llm_npc::readKv(tmp.path / "a.cfg");
