192	    sf::RectangleShape backdrop(sf::Vector2f(bounds.width + 24.f, bounds.height + 16.f));
193	    backdrop.setPosition(x - 12.f, y - 6.f);
194	    backdrop.setFillColor(sf::Color(10, 14, 22, 170));
195	    window.draw(backdrop);
196	
197	    text.setPosition(x, y);
198	    text.setFillColor(sf::Color::White);
199	    window.draw(text);
200	}
201	
202	}  // namespace
203	
204	int main() {
205	    const fs::path projectRoot = findProjectRoot();
206	    const fs::path configDir = projectRoot / "config";
207	
208	    const LlmConfig llmConfig = loadLlmConfig(configDir);
209	    std::cerr << "[llm_npc] model=" << llmConfig.model << " host=" << llmConfig.host << ":"
210	              << llmConfig.port << "\n";
211	
212	    KeyBindings bindings = KeyBindings::defaults();
213	    const fs::path bindingsPath = configDir / "keybindings.cfg";
214	    bindings.load(bindingsPath);
215	
216	    // World: the downtown map plus one NPC per persona file.
217	    LlmClient client(llmConfig);
218	    client.warmUp();  // preload the model so the first reply starts fast
219	
220	    World world(City::makeDowntown());
221	    std::vector<std::string> personaErrors;
222	    const auto roster = loadAllPersonas(projectRoot / "personas", &personaErrors);
223	    for (const auto& err : personaErrors) std::cerr << "[llm_npc] persona error: " << err << "\n";
224	    for (const auto& loaded : roster) {
225	        Npc npc(loaded.persona, client);
226	        npc.setPlacement(loaded.position, loaded.facingDeg, loaded.spotId);
227	        world.addNpc(std::move(npc));
228	    }
229	    std::cerr << "[llm_npc] loaded " << world.npcs().size() << " NPCs\n";
230	
231	    // Window with a legacy-GL 2.1 context (same recipe as cpp_shooter_game).
232	    sf::ContextSettings settings;
233	    settings.depthBits = 24;
234	    settings.stencilBits = 8;
235	    settings.antialiasingLevel = 4;
236	    settings.majorVersion = 2;
237	    settings.minorVersion = 1;
238	    sf::RenderWindow window(sf::VideoMode(1280, 720), "LLM NPC City", sf::Style::Default, settings);
239	    window.setVerticalSyncEnabled(true);
240	    window.setActive(true);
241	
242	    sf::Font font;
243	    const fs::path fontPath = findSystemFont();
244	    if (fontPath.empty() || !font.loadFromFile(fontPath.string())) {
245	        std::cerr << "[llm_npc] no system font found; UI cannot render text.\n";
246	        return 1;
247	    }
248	
249	    Renderer3D renderer;
250	    renderer.init();
251	
252	    DialogUI dialog(font);
253	    DialogueSession session;
254	    Menu menu(bindings, bindingsPath);
255	    // Late replies for conversations the player already walked away from
256	    // still need to reach the right NPC's history.
257	    std::unordered_map<std::uint64_t, int> pendingRoutes;
258	
259	    AppMode mode = AppMode::Playing;
260	    CameraPose camera;
261	    camera.position = Vec3{0.f, 0.f, 24.f};  // plaza south edge, facing the cart
262	    window.setMouseCursorVisible(false);
263	    centerMouse(window);
264	
265	    int nearbyNpc = -1;
266	    // Arrest bookkeeping: when an officer catches the player, the player is
267	    // held at the police station for a short sentence. wasCaught tracks each
268	    // NPC's previous catch latch so the moment of capture fires exactly once.
269	    float jailSecondsLeft = 0.f;
270	    std::vector<bool> wasCaught(world.npcs().size(), false);
271	    sf::Clock frameClock;
272	    while (window.isOpen()) {
273	        sf::Event event{};
274	        while (window.pollEvent(event)) {
275	            if (event.type == sf::Event::Closed) window.close();
276	            if (event.type == sf::Event::GainedFocus && mode == AppMode::Playing) centerMouse(window);
277	            // Release the cursor when focus leaves so the macOS disassociation
278	            // (see centerMouse) can't freeze the mouse in other apps.
279	            if (event.type == sf::Event::LostFocus) releaseMouse();
280	
281	            if (mode == AppMode::Playing && event.type == sf::Event::KeyPressed) {
282	                const bool menuKey = event.key.code == keyFromName(bindings.key(Action::OpenMenu)) ||
283	                                     event.key.code == sf::Keyboard::Escape;
284	                if (menuKey) {
285	                    menu.open();
286	                    mode = AppMode::Menu;
287	                    window.setMouseCursorVisible(true);
288	                    releaseMouse();
289	                } else if (event.key.code == keyFromName(bindings.key(Action::Talk)) && nearbyNpc >= 0) {
290	                    session.open(nearbyNpc);
291	                    Npc& npc = world.npcs()[static_cast<std::size_t>(nearbyNpc)];
292	                    npc.lookAt(camera.position);  // turn to the player as the chat opens
293	                    dialog.reset();
294	                    dialog.setInputEnabled(true);
295	                    dialog.swallowNextTextEntered();
296	                    dialog.appendLine({TranscriptLine::Kind::System, "",
297	                                       "You are talking to " + npc.persona().name + " (" +
298	                                           npc.persona().role + "). Enter sends, Esc leaves."});
299	                    mode = AppMode::Dialogue;
300	                    window.setMouseCursorVisible(true);
301	                    releaseMouse();
302	                }
303	                continue;
304	            }
305	
306	            if (mode == AppMode::Dialogue) {
307	                if (event.type == sf::Event::KeyPressed && event.key.code == sf::Keyboard::Escape) {
308	                    session.close();
309	                    dialog.endStreaming();
310	                    mode = AppMode::Playing;
311	                    window.setMouseCursorVisible(false);
312	                    centerMouse(window);
313	                    continue;
314	                }
315	                const std::string submitted = dialog.handleEvent(event);
316	                if (!submitted.empty() && session.isOpen()) {
317	                    Npc& npc = world.npcs()[static_cast<std::size_t>(session.npcIndex())];
318	                    if (!npc.waiting()) {
319	                        dialog.appendLine({TranscriptLine::Kind::Player, "You", submitted});
320	                        const std::uint64_t id = npc.ask(submitted);
321	                        session.submitted(id);
322	                        pendingRoutes[id] = session.npcIndex();
323	                        dialog.beginStreaming(npc.persona().name);
324	                        dialog.setInputEnabled(false);
325	                    }
326	                }
327	                continue;
328	            }
329	
330	            if (mode == AppMode::Menu) {
331	                switch (menu.handleEvent(event, window)) {
332	                    case MenuResult::Resume:
333	                        mode = AppMode::Playing;
334	                        window.setMouseCursorVisible(false);
335	                        centerMouse(window);
336	                        break;
337	                    case MenuResult::Quit:
338	                        window.close();
339	                        break;
340	                    case MenuResult::None:
341	                        break;
342	                }
343	            }
344	        }
345	        if (!window.isOpen()) break;
346	
347	        const float dt = std::min(0.03f, frameClock.restart().asSeconds());
348	
349	        if (mode == AppMode::Playing) {
350	            if (window.hasFocus()) handleMouseLook(window, camera);
351	
352	            // No walking out of a sentence; looking around is still allowed.
353	            if (jailSecondsLeft <= 0.f) {
354	                Vec3 wish{};
355	                if (isActionPressed(bindings, Action::MoveForward)) wish += flatForward(camera.yawDeg);
356	                if (isActionPressed(bindings, Action::MoveBackward)) wish += flatForward(camera.yawDeg) * -1.f;
357	                if (isActionPressed(bindings, Action::StrafeRight)) wish += flatRight(camera.yawDeg);
358	                if (isActionPressed(bindings, Action::StrafeLeft)) wish += flatRight(camera.yawDeg) * -1.f;
359	                wish = normalize(wish);
360	                const Vec3 target = camera.position + wish * (kWalkSpeed * dt);
361	                camera.position = world.city().resolveMovement(camera.position, target, kPlayerRadius);
362	            }
363	        } else if (mode == AppMode::Menu) {
364	            menu.update(dt);
365	        }
366	        if (mode != AppMode::Menu && jailSecondsLeft > 0.f) jailSecondsLeft -= dt;
367	
368	        // NPCs act on whatever instruction they last accepted (follow, chase,
369	        // face, gesture). This keeps running during dialogue so a companion
370	        // trails you while you talk, but the pause menu freezes the world.
371	        if (mode != AppMode::Menu) {
372	            for (Npc& npc : world.npcs()) npc.update(dt, camera.position, world.city());
373	        }
374	
375	        // The moment an officer catches the player: a short stay at the
376	        // station. The officer heads back to their post, and the player is
377	        // released where they were dropped off once the sentence runs out.
378	        for (std::size_t i = 0; i < world.npcs().size(); ++i) {
379	            Npc& npc = world.npcs()[i];
380	            const bool caughtNow = npc.hasCaughtPlayer();
381	            if (caughtNow && !wasCaught[i] && npc.persona().police) {
382	                jailSecondsLeft = kJailSeconds;
383	                if (const Building* station = world.city().findBuilding("police")) {
384	                    camera.position = Vec3{(station->minX + station->maxX) * 0.5f, 0.f,
385	                                           station->maxZ + 2.f};
386	                }
387	                npc.commandReturnHome();
388	                if (mode == AppMode::Dialogue) {
389	                    // Being hauled off ends any open conversation.
390	                    session.close();
391	                    dialog.endStreaming();
392	                    mode = AppMode::Playing;
393	                    window.setMouseCursorVisible(false);
394	                    centerMouse(window);
395	                }
396	            }
397	            wasCaught[i] = npc.hasCaughtPlayer();
398	        }
399	
400	        nearbyNpc = world.nearestNpcWithin(camera.position, kTalkRadius);
401	
402	        // Streamed fragments for the open conversation appear immediately.
403	        for (const auto& delta : client.drainDeltas()) {
404	            if (session.deltaArrived(delta.id, delta.text)) {
405	                dialog.appendStreamingDelta(delta.text);
406	            }
407	        }
408	
409	        // Completed replies land in NPC history even after the dialog closed.
410	        for (const auto& reply : client.drainReplies()) {
411	            const auto route = pendingRoutes.find(reply.id);
412	            if (route == pendingRoutes.end()) continue;
413	            Npc& npc = world.npcs()[static_cast<std::size_t>(route->second)];
414	            const auto text = npc.onReplyArrived(reply);
415	            pendingRoutes.erase(route);
416	
417	            if (session.replyArrived(reply.id, reply.ok)) {
418	                dialog.endStreaming();
419	                if (text) {
420	                    if (!text->empty()) {
421	                        dialog.appendLine({TranscriptLine::Kind::Npc, npc.persona().name, *text});
422	                    }
423	                    // Narrate any physical action so it's visible in the log,
424	                    // and so a wordless "tag-only" reply still shows something.
425	                    const std::string sd = stageDirection(npc.lastAction());
426	                    if (!sd.empty()) {
427	                        dialog.appendLine({TranscriptLine::Kind::System, "",
428	                                           npc.persona().name + " " + sd});
429	                    } else if (text->empty()) {
430	                        dialog.appendLine({TranscriptLine::Kind::System, "",
431	                                           "(" + npc.persona().name + " says nothing.)"});
432	                    }
433	                    // A summons mobilizes every officer in the city.
434	                    if (npc.lastAction() == NpcAction::CallPolice) {
435	                        for (Npc& officer : world.npcs()) {
436	                            if (officer.persona().police) officer.commandArrest();
437	                        }
438	                    }
439	                } else {
440	                    dialog.appendLine({TranscriptLine::Kind::System, "",
441	                                       "[" + npc.persona().name + " seems distracted: " +
442	                                           reply.errorMessage + "]"});
443	                }
444	                dialog.setInputEnabled(true);
445	            }
446	        }
447	
448	        // ---- 3D pass ----
449	        renderer.beginFrame(window, camera);
450	        renderer.drawCity(world.city());
451	        for (std::size_t i = 0; i < world.npcs().size(); ++i) {
452	            const Npc& npc = world.npcs()[i];
453	            NpcPose pose = NpcPose::None;
454	            if (npc.pose() == NpcAction::RaiseHand) pose = NpcPose::RaiseHand;
455	            else if (npc.pose() == NpcAction::Wave) pose = NpcPose::Wave;
456	            renderer.drawNpc(NpcVisual{npc.position(), npc.facingDeg(), static_cast<int>(i),
457	                                       pose, npc.gesturePhase(), faceForMood(npc.mood())});
458	        }
459	
460	        // ---- SFML overlay pass ----
461	        window.pushGLStates();
462	
463	        for (const Npc& npc : world.npcs()) {
464	            if (distanceXZ(camera.position, npc.position()) > kNameplateRange) continue;
465	            sf::Vector2f screen;
466	            if (!renderer.worldToScreen(npc.position() + Vec3{0.f, 2.15f, 0.f}, window, screen)) continue;
467	            sf::Text tag(npc.persona().name, font, 14);
468	            const sf::FloatRect bounds = tag.getLocalBounds();
469	            tag.setPosition(screen.x - bounds.width * 0.5f, screen.y - bounds.height);
470	            tag.setOutlineThickness(2.f);
471	            tag.setOutlineColor(sf::Color(0, 0, 0, 200));
472	            tag.setFillColor(sf::Color::White);
473	            window.draw(tag);
474	        }
475	
476	        if (mode == AppMode::Playing) {
477	            if (nearbyNpc >= 0) {
478	                const Npc& npc = world.npcs()[static_cast<std::size_t>(nearbyNpc)];
479	                drawCenteredHudText(window, font,
480	                                    "[" + bindings.key(Action::Talk) + "] Talk to " + npc.persona().name,
481	                                    20, static_cast<float>(window.getSize().y) - 84.f);
482	            }
483	            // Serving time: show the countdown while movement is locked.
484	            if (jailSecondsLeft > 0.f) {
485	                const int secs = static_cast<int>(jailSecondsLeft) + 1;
486	                drawCenteredHudText(window, font,
487	                                    "Arrested: disturbing the peace. Released in " +
488	                                        std::to_string(secs) + "s",
489	                                    22, static_cast<float>(window.getSize().y) - 120.f);
490	            }
491	            // Crosshair dot.
492	            sf::CircleShape dot(2.f);
493	            dot.setOrigin(2.f, 2.f);
494	            dot.setPosition(static_cast<float>(window.getSize().x) * 0.5f,
495	                            static_cast<float>(window.getSize().y) * 0.5f);
496	            dot.setFillColor(sf::Color(255, 255, 255, 200));
497	            window.draw(dot);
498	        } else if (mode == AppMode::Dialogue) {
499	            sf::RectangleShape dim(sf::Vector2f(static_cast<float>(window.getSize().x),
500	                                                static_cast<float>(window.getSize().y)));
501	            dim.setFillColor(sf::Color(8, 10, 16, 150));
502	            window.draw(dim);
503	            dialog.render(window);
504	        } else {
505	            menu.render(window, font);
506	        }
507	
508	        window.popGLStates();
509	        window.display();
510	    }
511	    return 0;
512	}
