64	// Unit forward vector on the ground plane for a yaw in degrees.
65	Vec3 flatForward(float yawDeg) {
66	    return normalize(Vec3{std::sin(degToRad(yawDeg)), 0.f, std::cos(degToRad(yawDeg))});
67	}
68	
69	// Ground-plane right vector; must match the camera basis or strafe inverts.
70	Vec3 flatRight(float yawDeg) {
71	    const Vec3 f = flatForward(yawDeg);
72	    return Vec3{-f.z, 0.f, f.x};
73	}
