75	// One frame of mouse look from raylib's relative mouse delta (cursor is
76	// disabled while playing, so the delta is raw movement — no re-centering,
77	// no macOS cursor-disassociation workaround needed anymore).
78	void applyMouseLook(LocalPlayer& pose) {
79	    const Vector2 delta = GetMouseDelta();
80	    // Mouse-right lowers yaw: the camera basis is right-handed with yaw
81	    // increasing toward +X (screen-left) — same derivation as the legacy
82	    // renderer's.
83	    pose.yawDeg -= delta.x * kMouseSensitivity;
84	    pose.pitchDeg = clampf(pose.pitchDeg - delta.y * kMouseSensitivity,
85	                           -kMaxPitchDeg, kMaxPitchDeg);
86	}
