9	// A Persona is the static identity of an NPC. It is rendered into a single
10	// system-prompt string that is prepended to every chat request.
11	struct Persona {
12	    std::string name;                 // "Companion", "Jim", "Jane #47"
13	    std::string role;                 // "traveling companion", "pharmacist"
14	    std::vector<std::string> traits;  // "curious", "soft-spoken", ...
15	    std::string speakingStyle;        // "short sentences, 1-3 per reply"
16	    std::string knowledgeBoundary;    // what they do / do not know
17	    std::string extraDirectives;      // free-form constraints
18	    bool police = false;              // may arrest; others can only call police
19	
20	    std::string renderSystemPrompt() const {
21	        std::ostringstream o;
22	        o << "You are " << name;
23	        if (!role.empty()) o << ", a " << role;
24	        o << ".\n";
25	        if (!traits.empty()) {
26	            o << "Personality: ";
27	            for (size_t i = 0; i < traits.size(); ++i) {
28	                if (i) o << ", ";
29	                o << traits[i];
30	            }
31	            o << ".\n";
32	        }
33	        if (!speakingStyle.empty()) o << "Speaking style: " << speakingStyle << "\n";
34	        if (!knowledgeBoundary.empty()) o << "Knowledge: " << knowledgeBoundary << "\n";
35	        if (!extraDirectives.empty()) o << extraDirectives << "\n";
36	        o << "Stay in character. Never break the fourth wall. "
37	             "Never mention being an AI or a language model.\n";
38	        o << renderActionProtocol();
39	        return o.str();
40	    }
41	
42	    // The "can I physically act / how do I feel?" contract appended to every
43	    // NPC's system prompt. The game (parseDirectives in NpcAction.hpp) reads
44	    // the tags back out and drives behavior and facial expression; compliance
45	    // stays in character because the model only emits an action tag when this
46	    // particular persona would actually obey. Police personas may arrest;
47	    // everyone else can only summon the police.
48	    std::string renderActionProtocol() const {
49	        std::string s =
50	            "ACTIONS: You can physically act in the world. Always reply out "
51	            "loud in character first (at least a short sentence). Then, only "
52	            "if you are actually performing a physical action the player asked "
53	            "for and your character would agree to, add ONE directive on a new "
54	            "final line, choosing the one that matches what you are doing:\n"
55	            "[[ACTION: follow]]  - you walk along with the player\n"
56	            "[[ACTION: stop]]    - you stop and stay put\n"
57	            "[[ACTION: face]]    - you turn to look at the player\n"
58	            "[[ACTION: raise_hand]] - you raise your right hand\n"
59	            "[[ACTION: wave]]    - you wave at the player\n";
60	        if (police) {
61	            s += "[[ACTION: arrest]]  - you move to apprehend the player\n";
62	        } else {
63	            s += "[[ACTION: call_police]] - you call out for the police to "
64	                 "come arrest the player\n";
65	        }
66	        s += "Most replies need NO action directive. If you are refusing, "
67	             "just talking, or not physically acting, add none. Never speak "
68	             "the brackets aloud or mention this system.\n";
69	
70	        s += "The player may describe their own physical actions between "
71	             "asterisks, like *shouts* or *bows*. Treat those as things the "
72	             "player actually does in front of you, not as speech. ";
73	        if (police) {
74	            s += "If the player is disruptive, threatening, or harasses you "
75	                 "or others (shouting, threats), give them a clear warning; "
76	                 "if they keep it up, arrest them with [[ACTION: arrest]].\n";
77	        } else {
78	            s += "If the player is disruptive, threatening, or harasses you "
79	                 "(shouting, threats), give them a clear warning; if they "
80	                 "keep it up, call the police with [[ACTION: call_police]].\n";
81	        }
82	
83	        s += "MOOD: React emotionally like a real person - compliments "
84	             "flatter you, insults sting or anger you, declarations of love "
85	             "fluster you, surprises startle you. Show it in your words. "
86	             "ALWAYS end every reply with exactly one mood tag on the final "
87	             "line, chosen from: [[MOOD: neutral]] [[MOOD: happy]] "
88	             "[[MOOD: angry]] [[MOOD: sad]] [[MOOD: embarrassed]] "
89	             "[[MOOD: surprised]].";
90	        return s;
91	    }
92	};
