16	// An NPC that delegates dialogue to the shared LlmClient. Holds its own persona
17	// and a bounded conversation history. Many NPCs can share one LlmClient.
18	class Npc {
19	   public:
20	    Npc(Persona persona, LlmClient& client, int maxHistoryTurns = 10);
21	
22	    // Sends the player's line to the LLM. Returns the in-flight request id.
23	    // The reply will appear in client.drainReplies() with that id; pass it back
24	    // into onReplyArrived() to update this NPC's history and surface text.
25	    std::uint64_t ask(const std::string& playerLine);
26	
27	    // Notify this NPC of a reply. Returns the assistant text if the id matches
28	    // a pending request from this NPC; nullopt otherwise. On success, the turn
29	    // is appended to history (capped to maxHistoryTurns_).
30	    std::optional<std::string> onReplyArrived(const ChatReply& reply);
31	
32	    // Places the NPC in the world: feet position, facing in degrees (0 looks
33	    // toward +Z), and the id of the building/prop they belong to. The spot is
34	    // remembered as "home" so ReturnHome can walk back to it later.
35	    void setPlacement(const Vec3& position, float facingDeg, std::string spotId) {
36	        position_ = position;
37	        facingDeg_ = facingDeg;
38	        homePosition_ = position;
39	        homeFacingDeg_ = facingDeg;
40	        spotId_ = std::move(spotId);
41	    }
42	
43	    // World-space feet position.
44	    const Vec3& position() const { return position_; }
45	
46	    // Facing direction in degrees; 0 looks toward +Z.
47	    float facingDeg() const { return facingDeg_; }
48	
49	    // Id of the building or prop this NPC stands at ("bakery", "bench", ...).
50	    const std::string& spotId() const { return spotId_; }
51	
52	    // Turns immediately to face `target` (e.g. the player starting a chat)
53	    // without changing the current behavior.
54	    void lookAt(const Vec3& target) { faceToward(target); }
55	
56	    // Advances world behavior by `dt` seconds: follows/chases the player and
57	    // turns to face them per the current behavior, sliding around buildings
58	    // via `city`, and counts down any active gesture pose. Pure game logic
59	    // (no LLM, no graphics) so it stays unit-testable.
60	    void update(float dt, const Vec3& playerPos, const City& city);
61	
62	    // The persistent movement behavior set by the last obeyed instruction.
63	    NpcAction behavior() const { return behavior_; }
64	
65	    // The transient gesture currently being shown (None when idle).
66	    NpcAction pose() const { return pose_; }
67	
68	    // Seconds since the active gesture began; drives wave animation phase.
69	    float gesturePhase() const { return gesturePhase_; }
70	
71	    // True once an Arrest behavior has reached the player. Latches until the
72	    // NPC is given a different instruction; lets the UI announce the catch.
73	    bool hasCaughtPlayer() const { return caughtPlayer_; }
74	
75	    // The action parsed from the most recent reply (None if the NPC didn't act
76	    // this turn). Lets the UI show a stage direction even when the model spoke
77	    // no words alongside its action tag.
78	    NpcAction lastAction() const { return lastAction_; }
79	
80	    // The emotional state read from the latest reply; decays back to Neutral
81	    // after a while. Drives the rendered facial expression.
82	    NpcMood mood() const { return mood_; }
83	
84	    // Orders this NPC (a summoned police officer) to chase the player down,
85	    // exactly as if its own reply had carried an arrest directive.
86	    void commandArrest() {
87	        behavior_ = NpcAction::Arrest;
88	        caughtPlayer_ = false;
89	    }
90	
91	    // Sends the NPC walking back to its spawn spot (e.g. a cop returning to
92	    // post after an arrest). Clears the catch latch.
93	    void commandReturnHome() {
94	        behavior_ = NpcAction::ReturnHome;
95	        caughtPlayer_ = false;
96	    }
97	
98	    const Persona& persona() const { return persona_; }
99	    const std::vector<ChatTurn>& history() const { return history_; }
100	    bool waiting() const { return pendingId_ != 0; }
101	
102	   private:
103	    Persona persona_;
104	    LlmClient& client_;
105	    int maxHistoryTurns_;
106	    std::vector<ChatTurn> history_;
107	    std::uint64_t pendingId_ = 0;
108	    std::string pendingUserLine_;
109	
110	    Vec3 position_{};
111	    float facingDeg_ = 0.f;
112	    std::string spotId_;
113	
114	    NpcAction behavior_ = NpcAction::None;    // persistent: follow/arrest/stop/face
115	    NpcAction pose_ = NpcAction::None;        // transient gesture overlay
116	    NpcAction lastAction_ = NpcAction::None;  // action from the latest reply
117	    NpcMood mood_ = NpcMood::Neutral;         // current expression
118	    float moodTimer_ = 0.f;                   // seconds until mood relaxes
119	    float poseTimer_ = 0.f;                   // seconds of gesture remaining
120	    float gesturePhase_ = 0.f;                // seconds elapsed in current gesture
121	    bool caughtPlayer_ = false;               // arrest reached the player
122	    Vec3 homePosition_{};                     // spawn spot for ReturnHome
123	    float homeFacingDeg_ = 0.f;               // spawn facing for ReturnHome
124	
125	    // Routes a freshly parsed action into behavior/gesture state.
126	    void applyAction(NpcAction action);
127	    void faceToward(const Vec3& target);
