// Tests for City: building lookup, circle collision, and movement sliding.
#include "City.hpp"
#include "doctest.h"

using llm_npc::Building;
using llm_npc::City;
using llm_npc::Vec3;

namespace {

// A minimal city with one 10x10 building centered at the origin.
City makeOneBlockCity() {
    City city = City::makeDowntown();
    // makeDowntown is the real map; for geometric edge cases we rely on its
    // known "cart" obstacle at [-3,3]x[-2,2] and the world bounds.
    return city;
}

}  // namespace

TEST_CASE("makeDowntown contains the five named shops") {
    City city = City::makeDowntown();
    for (const char* id : {"bakery", "police", "coffee", "library", "hardware"}) {
        const Building* b = city.findBuilding(id);
        REQUIRE_MESSAGE(b != nullptr, id);
        CHECK_FALSE(b->name.empty());
        CHECK(b->minX < b->maxX);
        CHECK(b->minZ < b->maxZ);
        CHECK(b->height > 0.f);
    }
    CHECK(city.findBuilding("no_such_building") == nullptr);
}

TEST_CASE("buildings stay inside world bounds") {
    City city = City::makeDowntown();
    for (const auto& b : city.buildings()) {
        CHECK(b.minX >= -city.halfSize());
        CHECK(b.maxX <= city.halfSize());
        CHECK(b.minZ >= -city.halfSize());
        CHECK(b.maxZ <= city.halfSize());
    }
}

TEST_CASE("circleIntersectsAny detects overlap and clear space") {
    City city = makeOneBlockCity();
    // Inside the hot-dog cart footprint.
    CHECK(city.circleIntersectsAny(0.f, 0.f, 0.6f));
    // Just outside the cart: x = 3 (cart edge) + 0.7 clearance, radius 0.6.
    CHECK_FALSE(city.circleIntersectsAny(3.7f, 0.f, 0.6f));
    // Touching via the radius: x = 3.4 means the 0.6 circle reaches 2.8 < 3.0.
    CHECK(city.circleIntersectsAny(3.5f, 0.f, 0.6f));
    // Open street, far from everything.
    CHECK_FALSE(city.circleIntersectsAny(0.f, 32.f, 0.6f));
}

TEST_CASE("resolveMovement allows free movement") {
    City city = makeOneBlockCity();
    const Vec3 from{0.f, 0.f, 32.f};
    const Vec3 to{1.f, 0.f, 33.f};
    const Vec3 res = city.resolveMovement(from, to, 0.6f);
    CHECK(res.x == doctest::Approx(1.f));
    CHECK(res.z == doctest::Approx(33.f));
}

TEST_CASE("resolveMovement blocks walking straight into a wall") {
    City city = makeOneBlockCity();
    // Approach the cart's +x face head-on.
    const Vec3 from{5.f, 0.f, 0.f};
    const Vec3 to{3.0f, 0.f, 0.f};  // would put the 0.6 circle inside the cart
    const Vec3 res = city.resolveMovement(from, to, 0.6f);
    CHECK(res.x == doctest::Approx(5.f));  // x move rejected
    CHECK(res.z == doctest::Approx(0.f));
}

TEST_CASE("resolveMovement slides along a wall on diagonal input") {
    City city = makeOneBlockCity();
    // Move diagonally into the cart's +x face: x is blocked, z should slide.
    const Vec3 from{4.f, 0.f, 0.f};
    const Vec3 to{2.f, 0.f, 1.5f};
    const Vec3 res = city.resolveMovement(from, to, 0.6f);
    CHECK(res.x == doctest::Approx(4.f));   // blocked axis dropped
    CHECK(res.z == doctest::Approx(1.5f));  // free axis applied
}

TEST_CASE("resolveMovement clamps to world bounds") {
    City city = makeOneBlockCity();
    const float h = city.halfSize();
    const Vec3 from{0.f, 0.f, 100.f};
    const Vec3 to{0.f, 0.f, h + 50.f};
    const Vec3 res = city.resolveMovement(from, to, 0.6f);
    CHECK(res.z == doctest::Approx(h - 0.6f));
}

TEST_CASE("every visible street obstacle has real collision") {
    // Traffic lights and park bushes are authored in City (the renderer
    // draws them from this list), so their visual footprints and colliders
    // can never diverge — walking through them is impossible by data.
    const llm_npc::City city = llm_npc::City::makeDowntown();
    const struct { const char* id; float x, z; } obstacles[] = {
        {"trafficlight_a", -23.f, -23.f}, {"trafficlight_b", -23.f, 41.f},
        {"trafficlight_c", 41.f, -23.f},  {"trafficlight_d", 41.f, 41.f},
        {"bush_a", 48.f, 48.f},           {"bush_b", 80.f, 52.f},
        {"bush_c", 52.f, 80.f},           {"bush_d", 76.f, 76.f},
    };
    for (const auto& o : obstacles) {
        CAPTURE(o.id);
        CHECK(city.findBuilding(o.id) != nullptr);
        CHECK(city.circleIntersectsAny(o.x, o.z, 0.3f));
    }
}

#include "City.hpp"

namespace llm_npc {

namespace {

// Squared distance from point (x, z) to the nearest point of building b.
float distSqToBuilding(const Building& b, float x, float z) {
    const float cx = clampf(x, b.minX, b.maxX);
    const float cz = clampf(z, b.minZ, b.maxZ);
    const float dx = x - cx;
    const float dz = z - cz;
    return dx * dx + dz * dz;
}

}  // namespace

City City::makeDowntown() {
    // Layout reference: 3x3 city blocks on a 64-unit pitch. Block centers sit
    // at -64/0/64 on each axis and each block spans +-24 around its center,
    // leaving 16-unit streets between blocks. The center block is an open
    // plaza; the north-east block is a park.
    City city;
    city.halfSize_ = 110.f;
    city.buildings_ = {
        // Named shops, fronts flush with their street edge.
        {"bakery", "Marge's Bakery", -84.f, -64.f, -56.f, -40.f, 12.f, 0},
        {"police", "City Police Station", -20.f, -80.f, 20.f, -40.f, 16.f, 1},
        {"coffee", "Bean There Coffee", 44.f, -62.f, 72.f, -40.f, 10.f, 2},
        {"library", "City Library", -80.f, -16.f, -40.f, 16.f, 15.f, 3},
        {"hardware", "Jensen Hardware", 40.f, -14.f, 72.f, 14.f, 11.f, 4},

        // Plaza furniture and street props (low obstacles).
        {"cart", "Gus's Hot Dogs", -3.f, -2.f, 3.f, 2.f, 3.f, 5},
        {"taxi_cab", "", 26.f, -6.f, 34.f, -1.f, 1.6f, 6},
        {"fountain", "", 60.f, 56.f, 68.f, 64.f, 1.5f, 7},
        {"bench", "", 66.f, 70.f, 70.f, 71.f, 0.6f, 8},

        // Street furniture with real collision — everything that renders
        // as a solid object is authored here so visuals and colliders can
        // never diverge (the renderer draws these from this list).
        {"trafficlight_a", "", -23.5f, -23.5f, -22.5f, -22.5f, 4.5f, 11},
        {"trafficlight_b", "", -23.5f, 40.5f, -22.5f, 41.5f, 4.5f, 11},
        {"trafficlight_c", "", 40.5f, -23.5f, 41.5f, -22.5f, 4.5f, 11},
        {"trafficlight_d", "", 40.5f, 40.5f, 41.5f, 41.5f, 4.5f, 11},
        {"bush_a", "", 46.8f, 46.8f, 49.2f, 49.2f, 1.1f, 12},
        {"bush_b", "", 78.8f, 50.8f, 81.2f, 53.2f, 1.1f, 12},
        {"bush_c", "", 50.8f, 78.8f, 53.2f, 81.2f, 1.1f, 12},
        {"bush_d", "", 74.8f, 74.8f, 77.2f, 77.2f, 1.1f, 12},

        // Parked cars, curbside on the two Z-running streets (KayKit cars
        // face along Z at identity and the Uniform draw path doesn't
        // rotate). Spots avoid the zebra crossings (x/z +-16 and +-48), the
        // junctions, shop doors, and every persona's home position. The
        // police car parks beside its station block.
        {"police_car", "", -28.8f, -64.f, -25.f, -57.5f, 1.5f, 13},
        {"hatchback_b", "", 25.f, -70.f, 28.6f, -63.5f, 1.35f, 13},
        {"sedan_a", "", 35.f, -7.5f, 38.8f, -1.5f, 1.35f, 13},
        {"sedan_b", "", 35.f, 60.f, 38.8f, 66.5f, 1.35f, 13},
        {"hatchback_a", "", -39.3f, 58.f, -35.8f, 64.5f, 1.35f, 13},

        // Alley props: dumpster + trash between the SW apartments, a bin in
        // the coffee/office alley.
        {"dumpster_a", "", -67.2f, -86.f, -63.2f, -83.5f, 1.4f, 14},
        {"trash_a", "", -62.5f, -87.4f, -61.1f, -86.f, 0.9f, 14},
        {"trash_b", "", 45.f, -65.4f, 46.2f, -64.2f, 0.7f, 14},

        // Unnamed filler so every block reads as a dense city.
        {"apt_a", "", -88.f, -88.f, -68.f, -70.f, 22.f, 9},
        {"apt_b", "", -60.f, -88.f, -40.f, -72.f, 18.f, 9},
        {"office_a", "", 44.f, -88.f, 88.f, -66.f, 26.f, 10},
        {"apts_c", "", -88.f, 44.f, -44.f, 84.f, 24.f, 9},
        {"tower", "", -24.f, 48.f, 24.f, 88.f, 30.f, 10},
    };
    return city;
}

const Building* City::findBuilding(const std::string& id) const {
    for (const auto& b : buildings_) {
        if (b.id == id) return &b;
    }
    return nullptr;
}

bool City::circleIntersectsAny(float x, float z, float radius) const {
    const float r2 = radius * radius;
    for (const auto& b : buildings_) {
        if (distSqToBuilding(b, x, z) < r2) return true;
    }
    return false;
}

Vec3 City::resolveMovement(const Vec3& from, const Vec3& to, float radius) const {
    const float lo = -halfSize_ + radius;
    const float hi = halfSize_ - radius;

    Vec3 pos = from;
    const float nx = clampf(to.x, lo, hi);
    if (!circleIntersectsAny(nx, pos.z, radius)) pos.x = nx;
    const float nz = clampf(to.z, lo, hi);
    if (!circleIntersectsAny(pos.x, nz, radius)) pos.z = nz;
    pos.y = to.y;
    return pos;
}

