    bool save(const std::string& npcId, const std::string& summary,
              const std::vector<ChatTurn>& transcript);

    // Npc ids currently stored (mostly for tests and debugging tools).
    std::vector<std::string> ids() const;

   private:
    sqlite3* db_ = nullptr;
};

}  // namespace llm_npc

