// forward (pitch dropped), which is exactly today's buggy behavior, so it
// compiles and callers link, but the real fix must add the pitch terms above.
// The skipped tests in tests/test_aim.cpp lock in the intended behavior.
inline Vec3 lookDirection(float yawDeg, float /*pitchDeg*/) {
    const float yr = degToRad(yawDeg);
