13	// Split a comma-separated list into trimmed, non-empty items.
14	std::vector<std::string> splitCsv(const std::string& s) {
15	    std::vector<std::string> out;
16	    std::string item;
17	    std::istringstream in(s);
18	    while (std::getline(in, item, ',')) {
19	        item = trim(item);
20	        if (!item.empty()) out.push_back(item);
21	    }
22	    return out;
23	}
24	
25	// Parses one "HH-HH, x, z, activity" schedule value. Hours may be
26	// fractional; the activity is everything after the third comma (it may
27	// itself contain commas). Returns false on any malformed piece.
28	bool parseScheduleEntry(const std::string& s, ScheduleEntry& out) {
29	    const auto c1 = s.find(',');
30	    if (c1 == std::string::npos) return false;
31	    const auto c2 = s.find(',', c1 + 1);
32	    if (c2 == std::string::npos) return false;
33	    const auto c3 = s.find(',', c2 + 1);
34	    if (c3 == std::string::npos) return false;
35	
36	    const std::string hours = trim(s.substr(0, c1));
37	    const auto dash = hours.find('-');
38	    if (dash == std::string::npos || dash == 0 || dash + 1 >= hours.size()) return false;
39	    try {
40	        out.startHour = std::stof(hours.substr(0, dash));
41	        out.endHour = std::stof(hours.substr(dash + 1));
42	        out.position.x = std::stof(trim(s.substr(c1 + 1, c2 - c1 - 1)));
43	        out.position.z = std::stof(trim(s.substr(c2 + 1, c3 - c2 - 1)));
44	        out.position.y = 0.f;
45	    } catch (const std::exception&) {
46	        return false;
47	    }
48	    if (out.startHour < 0.f || out.startHour >= 24.f || out.endHour < 0.f ||
49	        out.endHour >= 24.f) {
50	        return false;
51	    }
52	    out.activity = trim(s.substr(c3 + 1));
53	    return !out.activity.empty();
54	}
55	
56	// Parse "x, z" into a ground-plane position. Returns false on bad input.
57	bool parsePosition(const std::string& s, Vec3& out) {
58	    auto parts = splitCsv(s);
59	    if (parts.size() != 2) return false;
60	    try {
61	        out.x = std::stof(parts[0]);
62	        out.z = std::stof(parts[1]);
63	        out.y = 0.f;
64	    } catch (const std::exception&) {
65	        return false;
66	    }
67	    return true;
68	}
69	
70	}  // namespace
71	
72	PersonaParseResult parsePersonaText(const std::string& text, const std::string& id) {
73	    PersonaParseResult result;
74	    result.value.id = id;
75	
76	    std::istringstream in(text);
77	    std::string line;
78	    std::ostringstream extra;
79	    bool inExtra = false;
80	
81	    while (std::getline(in, line)) {
82	        if (!inExtra) {
83	            const std::string t = trim(line);
84	            if (t == "---") {
85	                inExtra = true;
86	                continue;
87	            }
88	            if (t.empty()) continue;
89	            const auto eq = t.find('=');
90	            if (eq == std::string::npos) {
91	                result.error = id + ": header line without '=': " + t;
92	                return result;
93	            }
94	            const std::string key = trim(t.substr(0, eq));
95	            const std::string val = trim(t.substr(eq + 1));
96	            if (key == "name") {
97	                result.value.persona.name = val;
98	            } else if (key == "role") {
99	                result.value.persona.role = val;
100	            } else if (key == "traits") {
101	                result.value.persona.traits = splitCsv(val);
102	            } else if (key == "style") {
103	                result.value.persona.speakingStyle = val;
104	            } else if (key == "knowledge") {
105	                result.value.persona.knowledgeBoundary = val;
106	            } else if (key == "spot") {
107	                result.value.spotId = val;
108	            } else if (key == "position") {
109	                if (!parsePosition(val, result.value.position)) {
110	                    result.error = id + ": bad position '" + val + "' (want: x, z)";
111	                    return result;
112	                }
113	            } else if (key == "facing") {
114	                try {
115	                    result.value.facingDeg = std::stof(val);
