114	std::vector<const PartDef*> partsForCategory(PartCategory category,
115	                                             const std::string& styleTag) {
116	    std::vector<const PartDef*> out;
117	    for (const PartDef& part : partCatalog()) {
118	        if (part.category != category) continue;
119	        if (styleTag == "any" || part.styleTag == "any" || part.styleTag == styleTag) {
120	            out.push_back(&part);
121	        }
122	    }
123	    return out;
124	}
