126	bool lookIsValid(const CharacterLook& look, std::string* why) {
127	    const PartDef* chosen[kPartCategoryCount] = {};
128	    for (int c = 0; c < kPartCategoryCount; ++c) {
129	        const std::string& id = look.partIds[c];
130	        if (id.empty()) {
131	            if (why) *why = "missing part for a category";
132	            return false;
133	        }
134	        chosen[c] = findPart(id);
135	        if (!chosen[c]) {
136	            if (why) *why = "unknown part: " + id;
137	            return false;
138	        }
139	        if (chosen[c]->category != static_cast<PartCategory>(c)) {
140	            if (why) *why = id + " is in the wrong category slot";
141	            return false;
142	        }
143	    }
144	    for (int a = 0; a < kPartCategoryCount; ++a) {
145	        for (int b = a + 1; b < kPartCategoryCount; ++b) {
146	            if (!styleCompatible(*chosen[a], *chosen[b])) {
147	                if (why) {
148	                    *why = chosen[a]->id + " and " + chosen[b]->id +
149	                           " mix incompatible styles";
150	                }
151	                return false;
152	            }
153	        }
154	    }
155	    bool paletteKnown = false;
156	    for (const PartPalette& palette : paletteCatalog()) {
157	        paletteKnown = paletteKnown || palette.id == look.paletteId;
158	    }
159	    if (!paletteKnown) {
160	        if (why) *why = "unknown palette: " + look.paletteId;
161	        return false;
162	    }
163	    return true;
164	}
