465	void RaylibRenderer::drawViewmodel(int weaponKind, float attackFraction) {
466	    if (weaponKind < 0 || weaponKind > 1) return;
467	    // The fist is invisible at rest — nothing floats in front of the
468	    // camera — and only appears as a punch while the swing plays out.
469	    const bool fist = weaponKind == 0;
470	    if (fist && attackFraction <= 0.01f) return;
471	
472	    // Everything below draws in CAMERA-LOCAL space: translate to the eye,
473	    // rotate by the camera's yaw and pitch, then draw axis-aligned shapes
474	    // with +z forward. The prop therefore pivots with the view instead of
475	    // reading as a world-axis-aligned floating block. In this local frame
476	    // +x is screen-LEFT (right-handed, y-up), so right-of-center offsets
477	    // are negative x.
478	    const Vector3 fwd{camera_.target.x - camera_.position.x,
479	                      camera_.target.y - camera_.position.y,
480	                      camera_.target.z - camera_.position.z};
481	    const float flen = std::sqrt(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
482	    if (flen < 1e-4f) return;
483	    const Vector3 f{fwd.x / flen, fwd.y / flen, fwd.z / flen};
484	    const float yawDeg = std::atan2(f.x, f.z) * RAD2DEG;
485	    const float pitchDeg = std::asin(std::max(-1.f, std::min(1.f, f.y))) * RAD2DEG;
486	
487	    const Color skin{224, 172, 138, 255};
488	    const Color sleeve{60, 64, 74, 255};
489	    const Color gunmetal{55, 58, 66, 255};
490	    const Color gripTone{38, 40, 46, 255};
