93	bool City::circleIntersectsAny(float x, float z, float radius, float feetY) const {
94	    const float r2 = radius * radius;
95	    // A building stops being solid once the mover's feet reach its top
96	    // (small tolerance so standing exactly on a roof doesn't wedge).
97	    const float clearance = feetY + 0.01f;
98	    for (const auto& b : buildings_) {
99	        if (b.height <= clearance) continue;
100	        if (distSqToBuilding(b, x, z) < r2) return true;
101	    }
102	    return false;
103	}
