105	float City::supportHeightAt(float x, float z, float radius, float feetY) const {
106	    const float r2 = radius * radius;
107	    float support = 0.f;  // the ground plane
108	    for (const auto& b : buildings_) {
109	        // Only tops at or below the feet can hold them up; anything higher
110	        // is a wall beside the mover, not a floor beneath them.
111	        if (b.height > feetY + 0.01f || b.height <= support) continue;
112	        if (distSqToBuilding(b, x, z) < r2) support = b.height;
113	    }
