121	    Vec3 pos = from;
122	    const float nx = clampf(to.x, lo, hi);
123	    if (!circleIntersectsAny(nx, pos.z, radius, from.y)) pos.x = nx;
124	    const float nz = clampf(to.z, lo, hi);
125	    if (!circleIntersectsAny(pos.x, nz, radius, from.y)) pos.z = nz;
126	    pos.y = to.y;
127	    return pos;
