25	Footprint footprintOf(const PlacedPiece& placed, const PieceDef& piece) {
26	    const float minX = static_cast<float>(placed.tileX) * kMapTileUnits;
27	    const float minZ = static_cast<float>(placed.tileZ) * kMapTileUnits;
28	    return {minX, minZ, minX + static_cast<float>(piece.tilesW) * kMapTileUnits,
29	            minZ + static_cast<float>(piece.tilesD) * kMapTileUnits};
