32	bool overlaps(const Footprint& a, const Footprint& b) {
33	    // Strict interior overlap — sharing an edge is legal (pieces tile).
34	    return a.minX < b.maxX && b.minX < a.maxX && a.minZ < b.maxZ && b.minZ < a.maxZ;
35	}
