37	// Distance-squared from a point to a footprint (clamp math, mirrors
38	// City's collision helper).
39	float distSqToFootprint(const Footprint& f, float x, float z) {
40	    const float cx = clampf(x, f.minX, f.maxX);
41	    const float cz = clampf(z, f.minZ, f.maxZ);
42	    const float dx = x - cx;
43	    const float dz = z - cz;
44	    return dx * dx + dz * dz;
45	}
