7	namespace llm_npc {
8	
9	// A Persona is the static identity of an NPC. It is rendered into a single
10	// system-prompt string that is prepended to every chat request.
11	struct Persona {
12	    std::string name;                 // "Companion", "Jim", "Jane #47"
13	    std::string role;                 // "traveling companion", "pharmacist"
14	    std::vector<std::string> traits;  // "curious", "soft-spoken", ...
15	    // TODO(traits step 2): add `std::vector<std::string> traitIds;` —
16	    // STRUCTURED traits from traits/*.trait (additive `trait =` persona
17	    // key; this free-text `traits` list stays as flavor). Compose in
18	    // renderSystemPrompt per the tested order contract in Trait.hpp.
19	    std::string speakingStyle;        // "short sentences, 1-3 per reply"
20	    std::string knowledgeBoundary;    // what they do / do not know
21	    std::string extraDirectives;      // free-form constraints
22	    bool police = false;              // may arrest; others can only call police
23	    bool armed = false;               // carries a weapon; retaliates when attacked
24	
25	    // Renders the system prompt with a persisted first-person memory from
26	    // earlier sessions woven in, so the NPC picks up where things left off.
27	    // An empty memory renders identically to renderSystemPrompt().
28	    std::string renderSystemPrompt(const std::string& memory) const {
29	        return renderSystemPrompt(memory, "");
30	    }
31	
32	    // Memory plus town gossip: the facts THIS character has heard (from the
33	    // shared world bus), so knowledge stays per-NPC. Both sections insert
34	    // before the action protocol — directive instructions stay last (small
35	    // models weight trailing instructions most). Empty strings render
36	    // identically to the plain prompt.
37	    std::string renderSystemPrompt(const std::string& memory,
38	                                   const std::string& gossip) const {
39	        std::string prompt = renderSystemPrompt();
40	        std::string section;
41	        if (!memory.empty()) {
42	            section += "What you remember from earlier meetings with this player: " +
43	                       memory + "\n";
44	        }
45	        if (!gossip.empty()) {
46	            section += "Things you have heard around town (bring them up when "
47	                       "relevant): " + gossip + "\n";
48	        }
49	        if (section.empty()) return prompt;
50	        const auto at = prompt.find("ACTIONS: ");
51	        if (at == std::string::npos) return prompt + section;
52	        prompt.insert(at, section);
53	        return prompt;
54	    }
55	
56	    std::string renderSystemPrompt() const {
57	        std::ostringstream o;
58	        o << "You are " << name;
59	        if (!role.empty()) o << ", a " << role;
60	        o << ".\n";
61	        if (!traits.empty()) {
62	            o << "Personality: ";
63	            for (size_t i = 0; i < traits.size(); ++i) {
64	                if (i) o << ", ";
65	                o << traits[i];
66	            }
67	            o << ".\n";
68	        }
69	        if (!speakingStyle.empty()) o << "Speaking style: " << speakingStyle << "\n";
70	        if (!knowledgeBoundary.empty()) o << "Knowledge: " << knowledgeBoundary << "\n";
71	        if (!extraDirectives.empty()) o << extraDirectives << "\n";
72	        o << "Stay in character. Never break the fourth wall. "
73	             "Never mention being an AI or a language model.\n";
74	        o << renderActionProtocol();
75	        return o.str();
76	    }
77	
78	    // The "can I physically act / how do I feel?" contract appended to every
79	    // NPC's system prompt. The game (parseDirectives in NpcAction.hpp) reads
80	    // the tags back out and drives behavior and facial expression; compliance
81	    // stays in character because the model only emits an action tag when this
82	    // particular persona would actually obey. Police personas may arrest;
83	    // everyone else can only summon the police.
84	    std::string renderActionProtocol() const {
85	        std::string s =
86	            "ACTIONS: You can physically act in the world. Always reply out "
87	            "loud in character first (at least a short sentence). Then, only "
88	            "if you are actually performing a physical action the player asked "
89	            "for and your character would agree to, add ONE directive on a new "
90	            "final line, choosing the one that matches what you are doing:\n"
91	            "[[ACTION: follow]]  - you walk along with the player\n"
92	            "[[ACTION: stop]]    - you stop and stay put\n"
93	            "[[ACTION: face]]    - you turn to look at the player\n"
94	            "[[ACTION: raise_hand]] - you raise your right hand\n"
95	            "[[ACTION: wave]]    - you wave at the player\n";
96	        if (police) {
97	            s += "[[ACTION: arrest]]  - you move to apprehend the player\n";
98	        } else {
99	            s += "[[ACTION: call_police]] - you call out for the police to "
100	                 "come arrest the player\n";
101	        }
102	        s += "Most replies need NO action directive. If you are refusing, "
103	             "just talking, or not physically acting, add none. Never speak "
104	             "the brackets aloud or mention this system.\n";
105	
106	        s += "The player may describe their own physical actions between "
