              "model = tiny:1b\n"
              "temperature = 0.25\n"
              "request_timeout_s = 7\n");
    auto cfg = llm_npc::loadLlmConfig(tmp.path);
    CHECK(cfg.host == "example.org");
    CHECK(cfg.port == 9999);
    CHECK(cfg.model == "tiny:1b");
    CHECK(cfg.temperature == doctest::Approx(0.25));
    CHECK(cfg.requestTimeoutSeconds == 7);
}

