195	void Assets::loadCharacter(const std::string& stem) {
196	    const std::string path = charDir_ + "/" + stem + ".glb";
197	    if (!std::filesystem::exists(path)) {
198	        std::cerr << "[llm_npc] missing character: " << path << "\n";
199	        return;
200	    }
201	    CharacterAsset character;
202	    character.model = LoadModel(path.c_str());
203	    if (character.model.meshCount == 0) {
204	        std::cerr << "[llm_npc] failed to load character: " << path << "\n";
205	        return;
206	    }
207	
208	    // The packs mix skinned body meshes with unskinned attachment meshes
209	    // (held items). raylib 5.5's CPU skinning dereferences boneWeights
210	    // unconditionally and crashes on the unskinned ones, so compact them
211	    // out — v1 characters simply don't show hand props.
212	    int kept = 0;
213	    for (int i = 0; i < character.model.meshCount; ++i) {
214	        if (character.model.meshes[i].boneWeights != nullptr) {
215	            character.model.meshes[kept] = character.model.meshes[i];
216	            character.model.meshMaterial[kept] = character.model.meshMaterial[i];
217	            ++kept;
218	        } else {
219	            UnloadMesh(character.model.meshes[i]);
220	        }
221	    }
222	    character.model.meshCount = kept;
223	    if (kept == 0) {
224	        std::cerr << "[llm_npc] character had no skinned meshes: " << path << "\n";
225	        UnloadModel(character.model);
226	        return;
227	    }
228	
229	    // Characters fog too. CPU skinning is unaffected: it writes animated
230	    // vertices into the mesh before drawing, and the fog shader consumes
231	    // only the standard position/texcoord/color attributes.
232	    if (fogLoaded_) {
233	        for (int i = 0; i < character.model.materialCount; ++i) {
234	            character.model.materials[i].shader = fogShader_;
235	        }
236	    }
237	
238	    character.clips = LoadModelAnimations(path.c_str(), &character.clipCount);
239	    for (int i = 0; i < character.clipCount; ++i) {
240	        const std::string name = character.clips[i].name;
241	        if (name == "Idle") character.idle = i;
242	        else if (name == "Walking_A") character.walk = i;
243	        else if (name == "Cheer") character.gesture = i;
244	        else if (name == "Death_A_Pose") character.death = i;
245	    }
246	    if (stem == "Knight") knightIndex_ = static_cast<int>(characters_.size());
247	    characters_.push_back(character);
248	}
