256	bool Assets::loadCityModel(const std::string& stem) {
257	    const std::string path = cityDir_ + "/" + stem + ".gltf";
258	    if (!std::filesystem::exists(path)) {
259	        std::cerr << "[llm_npc] missing model: " << path << " (using fallback shape)\n";
260	        return false;
261	    }
262	    Model model = LoadModel(path.c_str());
263	    if (model.meshCount == 0) {
264	        std::cerr << "[llm_npc] failed to load model: " << path << "\n";
265	        return false;
266	    }
267	    // Atmosphere: every material renders through the shared fog shader.
268	    // (UnloadModel leaves material shaders alone — raylib treats them as
269	    // user-owned precisely so they can be shared; the destructor unloads
270	    // fogShader_ exactly once.)
271	    if (fogLoaded_) {
272	        for (int i = 0; i < model.materialCount; ++i) {
273	            model.materials[i].shader = fogShader_;
274	        }
275	    }
276	    models_.emplace(stem, model);
277	    return true;
278	}
