164	void RaylibRenderer::drawCity(const City& city) {
165	    const float half = city.halfSize();
166	
167	    // Ground: grass base with the street grid and block slabs on top.
168	    DrawPlane({0.f, 0.f, 0.f}, {half * 2.f, half * 2.f}, kGrass);
169	
170	    // Streets: KayKit road tiles when the pack is present, flat asphalt
171	    // strips otherwise. Tile pitch = street width (16), centers at multiples
172	    // of 16 so the four junctions at (+-32, +-32) land exactly on tile
173	    // centers; the arm tiles beside each junction (+-16, +-48) carry zebra
174	    // crossings where the sidewalks meet. 13 tiles cover +-104; a compressed
175	    // end-cap tile spans the last 6 units to the +-110 map edge.
176	    const Model* straight = assets_.prop("road_straight");
177	    const Model* crossing = assets_.prop("road_straight_crossing");
178	    const Model* junction = assets_.prop("road_junction");
179	    if (city.hasStreets() && straight && crossing && junction) {
180	        constexpr float kTile = 16.f;
181	        for (const float sc : {-kStreetCenter, kStreetCenter}) {
182	            for (float t = -96.f; t <= 96.f; t += kTile) {
183	                if (t == -kStreetCenter || t == kStreetCenter) {
184	                    // Both streets pass through this tile; draw the 4-way
185	                    // junction art once (in the Z-running pass).
186	                    drawRoadTile(*junction, sc, t, kStreetWidth, kTile, false);
187	                    continue;
188	                }
189	                const float arm = std::fabs(std::fabs(t) - kStreetCenter);
190	                const Model& tile = (arm == kTile) ? *crossing : *straight;
191	                drawRoadTile(tile, sc, t, kStreetWidth, kTile, false);
192	                drawRoadTile(tile, t, sc, kTile, kStreetWidth, true);
193	            }
194	            for (const float e : {-107.f, 107.f}) {
195	                drawRoadTile(*straight, sc, e, kStreetWidth, 6.f, false);
196	                drawRoadTile(*straight, e, sc, 6.f, kStreetWidth, true);
197	            }
198	        }
199	    } else if (city.hasStreets()) {
200	        for (const float c : {-kStreetCenter, kStreetCenter}) {
201	            DrawCube({c, 0.02f, 0.f}, kStreetWidth, 0.04f, half * 2.f, kAsphalt);
202	            DrawCube({0.f, 0.02f, c}, half * 2.f, 0.04f, kStreetWidth, kAsphalt);
203	        }
204	    }
205	    // Block slabs: plaza (center) is pale stone, park (north-east) stays
206	    // grass, every other block gets a sidewalk-toned slab. Sandbox cities
207	    // (no authored street grid) stay plain grass.
208	    if (city.hasStreets()) {
209	        for (const float bx : {-64.f, 0.f, 64.f}) {
210	            for (const float bz : {-64.f, 0.f, 64.f}) {
211	                const bool plaza = bx == 0.f && bz == 0.f;
212	                const bool park = bx == 64.f && bz == 64.f;
213	                if (park) continue;
214	                DrawCube({bx, 0.04f, bz}, 48.f, 0.08f, 48.f, plaza ? kPlaza : kSidewalk);
215	            }
216	        }
217	    }
218	
219	    // Street furniture (traffic lights, bushes) renders through the same
220	    // buildings pass below — City authors their positions AND colliders,
221	    // so nothing visible can be walk-through.
222	
223	    // Buildings and street props from the collision AABBs — the models scale
224	    // to fit the authoritative footprints, never the other way around.
225	    for (const Building& b : city.buildings()) {
226	        // The fountain is composed from primitives (no pack model). Must be
227	        // dispatched by id BEFORE the model lookup: modelForBuilding falls
228	        // back to a hashed generic building for uncurated ids.
229	        // Compare the BASE id: sandbox instances carry a '#' suffix
230	        // ("fountain#4") and must hit the same composite recipe.
231	        if (b.id.substr(0, b.id.find('#')) == "fountain") {
232	            drawFountain(b, assets_.sizeSpecFor(b).worldHeight);
233	            continue;
234	        }
235	        if (const Model* model = assets_.modelForBuilding(b)) {
236	            const Assets::SizeSpec& spec = assets_.sizeSpecFor(b);
237	            if (spec.mode == Assets::SizeSpec::Mode::Uniform) {
238	                drawModelUniform(*model, (b.minX + b.maxX) * 0.5f,
239	                                 (b.minZ + b.maxZ) * 0.5f, spec.worldHeight, WHITE);
240	            } else {
241	                drawModelFittedToAABB(*model, b.minX, b.minZ, b.maxX, b.maxZ, b.height,
242	                                      WHITE);
243	            }
244	        } else {
245	            // Fallback primitive, tinted like the legacy renderer's boxes.
246	            const unsigned char tint =
247	                static_cast<unsigned char>(120 + (b.facadeKind * 37) % 90);
248	            const Vector3 center{(b.minX + b.maxX) * 0.5f, b.height * 0.5f,
249	                                 (b.minZ + b.maxZ) * 0.5f};
250	            DrawCube(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
251	                     Color{tint, tint, static_cast<unsigned char>(tint + 20), 255});
252	            DrawCubeWires(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
253	                          Color{40, 45, 60, 255});
254	        }
255	    }
256	}
