258	void RaylibRenderer::drawCharacter(const CharacterVisual& visual) {
259	    const Assets::CharacterAsset* character =
260	        assets_.characterFor(visual.variantSeed, visual.police);
261	    if (!character) {
262	        // No pack: marker cylinder, same as the pre-asset placeholder.
263	        const Vec3& p = visual.position;
264	        DrawCylinder({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{200, 120, 80, 255});
265	        DrawCylinderWires({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{60, 30, 20, 255});
266	        return;
267	    }
268	
269	    // Pick the clip: death overrides everything, gestures interrupt,
270	    // then walk/idle by movement.
271	    int clip = visual.walking ? character->walk : character->idle;
272	    if (visual.gesturePhase > 0.f && character->gesture >= 0) clip = character->gesture;
273	    if (visual.dead && character->death >= 0) clip = character->death;
274	
275	    AnimState& state = anim_[visual.variantSeed];
276	    if (state.clip != clip) {
277	        state.clip = clip;
278	        state.time = 0.f;
279	    }
280	    state.time += GetFrameTime();
281	    if (clip >= 0 && clip < character->clipCount) {
282	        // raylib bakes glTF animations at ~60 samples/second; loop by frame.
283	        const ModelAnimation& animation = character->clips[clip];
284	        const int frame =
285	            static_cast<int>(state.time * 60.f) % (animation.frameCount > 0
286	                                                       ? animation.frameCount
287	                                                       : 1);
288	        // CPU skinning on the shared model right before this entity's draw,
289	        // so several entities can reuse one model with different clocks.
290	        UpdateModelAnimation(character->model, animation, frame);
291	    }
292	
293	    // Uniform height: scale so every character stands ~1.8 units tall, feet
294	    // on the ground, rotated to the game's facing convention (0 → +Z).
295	    const BoundingBox bb = GetModelBoundingBox(character->model);
296	    const float modelHeight = bb.max.y - bb.min.y;
297	    const float s = modelHeight > 0.f ? 1.8f / modelHeight : 1.f;
298	    const Vector3 position{visual.position.x, -bb.min.y * s, visual.position.z};
299	    DrawModelEx(character->model, position, Vector3{0.f, 1.f, 0.f}, visual.facingDeg,
300	                Vector3{s, s, s}, WHITE);
301	
302	    // Non-neutral moods float as an emote above the head — the same six
303	    // procedural faces the legacy renderer painted on, now billboarded.
304	    // The dead don't emote.
305	    if (!visual.dead && visual.face != NpcFace::Neutral) {
306	        DrawBillboard(camera_, assets_.faceTexture(visual.face),
307	                      Vector3{visual.position.x, 2.45f, visual.position.z}, 0.55f,
308	                      WHITE);
309	    }
310	}
