465	    } else if (part.id == "eyes_glasses") {
466	        // Two framed lenses joined by a bridge, pupils inside.
467	        const float dx = dim.x * 0.5f - dim.y * 0.55f;
468	        for (const float side : {-1.f, 1.f}) {
