471	            DrawSphere({at.x + side * dx, cy, at.z + dim.z * 0.15f},
472	                       dim.y * 0.32f, c.skin);
473	        }
474	        DrawCube({at.x, cy + dim.y * 0.12f, at.z}, dx * 0.9f, dim.y * 0.18f,
475	                 dim.z * 0.5f, c.dark);
476	    } else if (part.id == "eyes_angry") {
477	        // Pupils under a heavy single brow bar.
478	        const float dx = dim.x * 0.5f - dim.y * 0.5f;
479	        DrawSphere({at.x - dx, cy - dim.y * 0.15f, at.z}, dim.y * 0.45f, c.dark);
480	        DrawSphere({at.x + dx, cy - dim.y * 0.15f, at.z}, dim.y * 0.45f, c.dark);
481	        DrawCube({at.x, cy + dim.y * 0.42f, at.z}, dim.x * 0.94f,
482	                 dim.y * 0.30f, dim.z, c.dark);
483	    } else if (part.id == "mouth_smile") {
484	        // A wide low bar with raised end dots reads as an upturned smile.
485	        DrawCube({at.x, cy - dim.y * 0.20f, at.z}, dim.x * 0.68f,
486	                 dim.y * 0.38f, dim.z, c.dark);
487	        DrawSphere({at.x - dim.x * 0.42f, cy + dim.y * 0.15f, at.z},
488	                   dim.y * 0.30f, c.dark);
489	        DrawSphere({at.x + dim.x * 0.42f, cy + dim.y * 0.15f, at.z},
490	                   dim.y * 0.30f, c.dark);
491	    } else if (part.id == "mouth_open" || part.id == "mouth_o") {
492	        // A flattened dark sphere: tall ellipse (open) or small ring (o).
493	        rlPushMatrix();
494	        rlTranslatef(at.x, cy, at.z);
495	        rlScalef(1.f, dim.y / dim.x, 0.35f);
496	        DrawSphere({0.f, 0.f, 0.f}, dim.x * 0.5f, c.dark);
497	        rlPopMatrix();
498	    } else if (part.id == "mouth_neutral") {
499	        DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, c.dark);
500	    } else if (part.category == PartCategory::Eyes) {
501	        if (part.id == "eyes_visor") {
502	            DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, c.dark);
503	        } else {
504	            // Two pupils split across the part's declared width.
505	            const float dx = dim.x * 0.5f - dim.y * 0.5f;
506	            DrawSphere({at.x - dx, cy, at.z}, dim.y * 0.5f, c.dark);
507	            DrawSphere({at.x + dx, cy, at.z}, dim.y * 0.5f, c.dark);
508	        }
509	    } else if (part.localSize.y > 0.f) {
510	        // Generic recipe: any part without a bespoke shape renders as
511	        // its declared box (skin for heads, hair on top, outfit below)
512	        // so NEW catalog parts appear immediately, just plainly.
513	        const Color color = part.category == PartCategory::Head ? c.skin
514	                            : part.category == PartCategory::Hair ? c.hair
515	                                                                  : c.outfit;
516	        DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, color);
517	    }
518	}
