522	void RaylibRenderer::drawCompositeCharacter(const CharacterLook& look,
523	                                            const Vec3& position, float facingDeg,
524	                                            bool walking, float phase, NpcFace face,
525	                                            bool dead) {
526	    const AssembledLook assembled = assembleLook(look);
527	    if (!assembled.ok) {
528	        // Invalid/stale look: the same marker cylinder the pack path uses.
529	        DrawCylinder({position.x, 0.f, position.z}, 0.35f, 0.35f, 1.8f, 12,
530	                     Color{200, 120, 80, 255});
531	        return;
532	    }
533	    // ONE uniform scale takes the whole assembly to the same height
534	    // contract pack characters use — parts were snapped in local space, so
535	    // proportions and socket alignment survive any future contract change.
536	    const float s = 1.8f / assembled.height;
537	
538	    const PartPalette* palette = &paletteCatalog().front();
539	    for (const PartPalette& candidate : paletteCatalog()) {
540	        if (candidate.id == look.paletteId) palette = &candidate;
541	    }
542	    const RecipeColors colors{
543	        Color{palette->skin[0], palette->skin[1], palette->skin[2], 255},
544	        Color{palette->hair[0], palette->hair[1], palette->hair[2], 255},
545	        Color{palette->outfit[0], palette->outfit[1], palette->outfit[2], 255},
546	        Color{38, 38, 44, 255}};
547	
548	    // Whole-figure transform: facing + procedural walk bob. Parts then draw
549	    // at their assembly-local positions and rotate correctly for free.
550	    // Death pose: the figure tips onto its back (a rigid tip-over, the
551	    // composite counterpart of the pack models' death clip), lifted a
552	    // little so the torso doesn't sink through the ground slab.
553	    const float bob = (walking && !dead) ? std::fabs(std::sin(phase * 7.f)) * 0.05f : 0.f;
554	    rlPushMatrix();
555	    rlTranslatef(position.x, position.y + bob + (dead ? 0.30f : 0.f), position.z);
556	    rlRotatef(facingDeg, 0.f, 1.f, 0.f);
557	    if (dead) rlRotatef(-90.f, 1.f, 0.f, 0.f);
558	
559	    // Cartoon outline, classic inverted hull (issue #103): every recipe is
560	    // issued TWICE — first inflated about its part's center, near-black,
561	    // with FRONT faces culled (so only a rim of the enlarged copy survives
562	    // around the real geometry), then normally. The passes are grouped —
563	    // not interleaved per part — because the cull-face switch must drain
564	    // the rlgl batch; two drains per character instead of two per part.
565	    constexpr float kHullScale = 1.06f;
566	    const RecipeColors outlineColors{kOutlineColor, kOutlineColor,
567	                                     kOutlineColor, kOutlineColor};
568	    rlDrawRenderBatchActive();
569	    rlSetCullFace(RL_CULL_FACE_FRONT);
570	    for (const PlacedPart& placed : assembled.parts) {
571	        const Vec3 at = placed.position * s;
572	        const Vec3 dim = placed.part->localSize * s;
573	        const float cy = at.y + dim.y * 0.5f;
574	        rlPushMatrix();  // inflate about the part's center, not the feet
575	        rlTranslatef(at.x, cy, at.z);
576	        rlScalef(kHullScale, kHullScale, kHullScale);
577	        rlTranslatef(-at.x, -cy, -at.z);
578	        drawPartRecipe(*placed.part, at, dim, outlineColors);
579	        rlPopMatrix();
580	    }
581	    rlDrawRenderBatchActive();
582	    rlSetCullFace(RL_CULL_FACE_BACK);
583	
584	    for (const PlacedPart& placed : assembled.parts) {
585	        // Anchor and size in world units — the contract scale is applied
586	        // HERE so recipes never see it.
587	        drawPartRecipe(*placed.part, placed.position * s,
588	                       placed.part->localSize * s, colors);
589	    }
590	    rlPopMatrix();
591	
592	    // Same emote billboard the pack path draws, at the same height — the
593	    // two render paths must stay indistinguishable to the player. The dead
594	    // don't emote.
595	    if (!dead && face != NpcFace::Neutral) {
596	        DrawBillboard(camera_, assets_.faceTexture(face),
597	                      Vector3{position.x, 2.45f, position.z}, 0.55f, WHITE);
598	    }
599	}
