611	bool RaylibRenderer::screenToGround(Vector2 screen, Vec3& out) const {
612	    const Ray ray = GetMouseRay(screen, camera_);
613	    if (ray.direction.y >= -1e-4f) return false;  // parallel or skyward
614	    const float t = -ray.position.y / ray.direction.y;
615	    out = Vec3{ray.position.x + ray.direction.x * t, 0.f,
616	               ray.position.z + ray.direction.z * t};
617	    return true;
618	}
