643	void RaylibRenderer::drawViewmodel(int weaponKind, float attackFraction) {
644	    if (weaponKind < 0 || weaponKind > 1) return;
645	    // The fist is invisible at rest — nothing floats in front of the
646	    // camera — and only appears as a punch while the swing plays out.
647	    const bool fist = weaponKind == 0;
648	    if (fist && attackFraction <= 0.01f) return;
649	
650	    // Everything below draws in CAMERA-LOCAL space: translate to the eye,
651	    // rotate by the camera's yaw and pitch, then draw axis-aligned shapes
652	    // with +z forward. The prop therefore pivots with the view instead of
653	    // reading as a world-axis-aligned floating block. In this local frame
654	    // +x is screen-LEFT (right-handed, y-up), so right-of-center offsets
655	    // are negative x.
656	    const Vector3 fwd{camera_.target.x - camera_.position.x,
657	                      camera_.target.y - camera_.position.y,
658	                      camera_.target.z - camera_.position.z};
659	    const float flen = std::sqrt(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
660	    if (flen < 1e-4f) return;
661	    const Vector3 f{fwd.x / flen, fwd.y / flen, fwd.z / flen};
662	    const float yawDeg = std::atan2(f.x, f.z) * RAD2DEG;
663	    const float pitchDeg = std::asin(std::max(-1.f, std::min(1.f, f.y))) * RAD2DEG;
664	
665	    // The avatar's palette colors the arm and hand — the one first-person
666	    // surface where the player sees their own look (issue #106).
667	    const Color skin = avatarSkin_;
668	    const Color sleeve = avatarOutfit_;
669	    const Color gunmetal{55, 58, 66, 255};
670	    const Color gripTone{38, 40, 46, 255};
671	
672	    rlPushMatrix();
673	    rlTranslatef(camera_.position.x, camera_.position.y, camera_.position.z);
674	    rlRotatef(yawDeg, 0.f, 1.f, 0.f);
675	    rlRotatef(-pitchDeg, 1.f, 0.f, 0.f);
676	
677	    if (fist) {
678	        // attackFraction runs 1 → 0 across the swing; sin turns that into
679	        // extend-then-retract, so the arm shoots out from the lower right
680	        // and pulls back — a punch, not a hovering prop.
681	        const float ext = std::sin(attackFraction * PI);
682	        const float reach = 0.34f + 0.55f * ext;
683	        // Sleeve forearm rising slightly toward screen center, fist at the
684	        // end. Local vectors — the matrix above carries them to the world.
685	        DrawCylinderEx(Vector3{-0.26f, -0.40f, 0.16f},
686	                       Vector3{-0.22f, -0.30f + 0.08f * ext, reach},
687	                       0.055f, 0.045f, 10, sleeve);
688	        DrawSphere(Vector3{-0.22f, -0.30f + 0.08f * ext, reach}, 0.075f, skin);
689	    } else {
690	        // Pistol: held silhouette (slide + barrel + grip + hand) with a
691	        // recoil kick — back and muzzle-up — driven by attackFraction.
692	        rlTranslatef(0.f, 0.f, -0.07f * attackFraction);
693	        rlRotatef(-7.f * attackFraction, 1.f, 0.f, 0.f);
694	        DrawCube(Vector3{-0.26f, -0.26f, 0.50f}, 0.045f, 0.075f, 0.26f, gunmetal);
695	        DrawCylinderEx(Vector3{-0.26f, -0.25f, 0.60f}, Vector3{-0.26f, -0.25f, 0.75f},
696	                       0.018f, 0.018f, 10, gunmetal);
697	        DrawCube(Vector3{-0.26f, -0.345f, 0.44f}, 0.04f, 0.11f, 0.055f, gripTone);
698	        DrawSphere(Vector3{-0.26f, -0.31f, 0.43f}, 0.042f, skin);  // hand
699	    }
700	    rlPopMatrix();
701	}
