// #139 verification: assembled quaternius mesh characters (random default
// looks) beside a stored core look, at the same 1.8u contract height.
#include "raylib.h"

#include "Assets.hpp"
#include "CharacterParts.hpp"
#include "RaylibRenderer.hpp"

using namespace llm_npc;

int main(int argc, char** argv) {
    InitWindow(1280, 720, "part mesh testbed");
    SetTargetFPS(60);
    Assets assets("assets");
    RaylibRenderer renderer(assets);
    renderer.setTimeOfDay(12.f);

    CameraPose pose;
    pose.position = Vec3{0.f, 0.f, -4.2f};
    pose.pitchDeg = -4.f;

    CharacterLook core;
    core.part(PartCategory::Body) = "body_round";
    core.part(PartCategory::Head) = "head_round";
    core.part(PartCategory::Eyes) = "eyes_dot";
    core.part(PartCategory::Hair) = "hair_tuft";
    core.part(PartCategory::Mouth) = "mouth_smile";
    core.paletteId = "warm";

    for (int frame = 0; frame < 60; ++frame) {
        BeginDrawing();
        ClearBackground(Color{135, 190, 235, 255});
        renderer.beginFrame(pose);
        DrawPlane(Vector3{0.f, 0.f, 0.f}, Vector2{40.f, 40.f},
                  Color{205, 205, 190, 255});
        for (int v = 0; v < 4; ++v) {
            renderer.drawCompositeCharacter(
                randomizeLook(static_cast<unsigned>(argc > 2 ? atoi(argv[2]) : 1) + v),
                Vec3{-3.3f + 1.65f * static_cast<float>(v), 0.f, 0.f}, 180.f,
                false, 0.f);
        }
        renderer.drawCompositeCharacter(core, Vec3{3.3f, 0.f, 0.f}, 180.f,
                                        false, 0.f);
        renderer.endFrame();
        EndDrawing();
    }
    TakeScreenshot(argv[1]);
