// Probe: does UpdateModelAnimation change the Quaternius bind pose, and
// which Idle frame reads as a natural stance?
#include <stdio.h>
#include <string.h>
#include "raylib.h"
int main(void) {
    InitWindow(1280, 720, "pose probe");
    SetTargetFPS(60);
    const char* path = "assets/models/characters_modular/Adventurer.gltf";
    Model model = LoadModel(path);
    int clipCount = 0;
    ModelAnimation* clips = LoadModelAnimations(path, &clipCount);
    int idle = -1;
    for (int i = 0; i < clipCount; i++)
        if (strcmp(clips[i].name, "Idle") == 0) idle = i;
    printf("idle=%d frames=%d\n", idle, idle >= 0 ? clips[idle].frameCount : -1);

    Camera3D cam = {0};
    cam.position = (Vector3){0.f, 1.4f, -6.f};
    cam.target = (Vector3){0.f, 1.f, 0.f};
    cam.up = (Vector3){0.f, 1.f, 0.f};
    cam.fovy = 45.f;
    cam.projection = CAMERA_PERSPECTIVE;

    const int frames[4] = {0, 10, 25, 40};
    for (int f = 0; f < 90; f++) {
        BeginDrawing();
        ClearBackground(RAYWHITE);
        BeginMode3D(cam);
        for (int k = 0; k < 4; k++) {
            if (idle >= 0)
                UpdateModelAnimation(model, clips[idle],
