using namespace llm_npc;

int main(int argc, char** argv) {
    InitWindow(1280, 720, "faces testbed");
    SetTargetFPS(60);
    Assets assets("assets");
    RaylibRenderer renderer(assets);
    renderer.setTimeOfDay(12.f);

    CameraPose pose;
