        BeginDrawing();
        ClearBackground(Color{135, 190, 235, 255});
        renderer.beginFrame(pose);
        DrawPlane(Vector3{0.f, 0.f, 0.f}, Vector2{40.f, 40.f},
                  Color{205, 205, 190, 255});
        for (int v = 0; v < 5; ++v) {
            look.part(PartCategory::Eyes) = eyePicks[v];
            look.part(PartCategory::Mouth) = mouthPicks[v];
            renderer.drawCompositeCharacter(
                look, Vec3{-2.4f + 1.2f * static_cast<float>(v), 0.f, 0.f},
                180.f, false, 0.f, moods[v]);
        }
        renderer.endFrame();
        EndDrawing();
    }
    TakeScreenshot(argv[1]);
    CloseWindow();
    return 0;
}
