1	#pragma once
2	
3	#include "raylib.h"
4	
5	#include <string>
6	#include <unordered_map>
7	#include <vector>
8	
9	#include "City.hpp"
10	#include "FaceTexture.hpp"
11	
12	namespace llm_npc {
13	
14	// Loads and owns every model, animation, and generated face texture, once,
15	// at startup (no mid-game loads — no frame hitches). Maps stable game
16	// identifiers → assets the same way the legacy renderer mapped them to
17	// procedural tints:
18	//   - Building::id ("bakery", "police", ...)  → curated model pick
19	//   - other buildings                         → generic pick hashed from id
20	//   - character variantSeed (NPC index, 1000+playerId) → character model
21	// Missing files degrade to primitives, never crash.
22	class Assets {
23	   public:
24	    // Searches `assetsDir` (assets/ at the project root — the tree
25	    // tools/fetch_assets.sh produces). Missing dir → loaded() stays false
26	    // and every accessor returns its fallback.
27	    explicit Assets(const std::string& assetsDir);
28	    ~Assets();
29	
30	    Assets(const Assets&) = delete;
31	    Assets& operator=(const Assets&) = delete;
32	
33	    // False when the city asset tree was missing/unreadable; main.cpp shows
34	    // the "run tools/fetch_assets.sh" notice and primitives are drawn.
35	    bool loaded() const { return loaded_; }
36	
37	    // How an entity's model maps into world space — the size CONTRACT that
38	    // makes relative scale independent of any specific asset's native
39	    // dimensions (swap the art pack, keep the sizes):
40	    //   Fill    — stretch to the collision AABB exactly (buildings: the
41	    //             visual must occupy its whole footprint).
42	    //   Uniform — scale uniformly to `worldHeight`, grounded and centered on
43	    //             the footprint (vehicles/props: proportions are part of the
44	    //             asset's identity; the AABB stays collision-only).
45	    struct SizeSpec {
46	        enum class Mode { Fill, Uniform };
47	        Mode mode = Mode::Fill;
48	        float worldHeight = 0.f;  // Uniform only; Fill takes the AABB height
49	    };
50	
51	    // The size contract for a building/prop entity, by id. Unlisted ids
52	    // default to Fill (dense city blocks must fill their footprints).
53	    const SizeSpec& sizeSpecFor(const Building& building) const;
54	
55	    // Model for a building; named spots (bakery, police, ...) get curated
56	    // picks, filler rotates through the generic buildings by id hash.
57	    // nullptr → caller draws the fallback cube.
58	    const Model* modelForBuilding(const Building& building) const;
59	
60	    // Named prop/road models by pack file stem ("road_straight", "bush",
61	    // "car_police", ...). nullptr when absent.
62	    const Model* prop(const std::string& stem) const;
63	
64	    // One rigged character: the model plus its animation clips, with the
65	    // clip indexes the renderer switches between resolved by name at load.
66	    struct CharacterAsset {
67	        Model model{};
68	        ModelAnimation* clips = nullptr;
69	        int clipCount = 0;
70	        int idle = -1;     // "Idle"
71	        int walk = -1;     // "Walking_A"
72	        int gesture = -1;  // "Cheer" — stands in for wave/raise-hand
73	        int death = -1;    // "Death_A_Pose" — collapsed on the ground
74	    };
75	
76	    // Character for a stable variant seed; police always get the Knight (the
77	    // armored silhouette reads as a uniform). nullptr → capsule fallback.
78	    const CharacterAsset* characterFor(int variantSeed, bool police) const;
79	
80	    // The baked emote texture for a mood face (always available — baked at
81	    // construction, no asset download involved).
82	    const Texture2D& faceTexture(NpcFace face) const {
83	        return faces_[static_cast<std::size_t>(face)];
84	    }
85	
86	    // The atmosphere shader (distance fog + warm tint), assigned to every
87	    // model material at load. The renderer also wraps the primitive batch
88	    // in it (BeginShaderMode) so ground/props haze consistently with
89	    // models. nullptr when shader compilation failed (plain look).
90	    const Shader* fogShader() const { return fogLoaded_ ? &fogShader_ : nullptr; }
91	
92	    // Locations of the shader's per-frame uniforms: camera position, plus
93	    // fog color and scene light level, which the renderer drives every
94	    // frame from the shared world clock's day/night curves.
