23	// Atmosphere shader: distance fog toward the sky color plus a subtle warm
24	// tint, over the standard texture * diffuse * vertex-color pipeline. The
25	// vertex stage passes world-space position (matModel is identity for rlgl
26	// batch primitives, whose vertices are already world-space, so the same
27	// shader serves models AND primitives). GLSL 330 — the core profile raylib
28	// uses on desktop.
29	constexpr const char* kFogVertexShader = R"(
30	#version 330
31	in vec3 vertexPosition;
32	in vec2 vertexTexCoord;
33	in vec4 vertexColor;
34	uniform mat4 mvp;
35	uniform mat4 matModel;
36	out vec2 fragTexCoord;
37	out vec4 fragColor;
38	out vec3 fragPosition;
39	void main() {
40	    fragPosition = vec3(matModel * vec4(vertexPosition, 1.0));
41	    fragTexCoord = vertexTexCoord;
42	    fragColor = vertexColor;
43	    gl_Position = mvp * vec4(vertexPosition, 1.0);
44	}
45	)";
46	
47	constexpr const char* kFogFragmentShader = R"(
48	#version 330
49	in vec2 fragTexCoord;
50	in vec4 fragColor;
51	in vec3 fragPosition;
52	uniform sampler2D texture0;
53	uniform vec4 colDiffuse;
54	uniform vec3 cameraPos;
55	uniform vec4 fogColor;
56	uniform float fogDensity;
57	uniform float lightLevel;
58	out vec4 finalColor;
59	void main() {
60	    vec4 texel = texture(texture0, fragTexCoord) * colDiffuse * fragColor;
61	    vec3 warm = texel.rgb * vec3(1.06, 1.0, 0.92) * lightLevel;
62	    float d = length(cameraPos - fragPosition) * fogDensity;
63	    float fog = 1.0 - exp(-d * d);
64	    finalColor = vec4(mix(warm, fogColor.rgb, fog), texel.a);
65	}
66	)";
