70	Assets::Assets(const std::string& assetsDir) {
71	    // Mood emotes are procedural — baked here regardless of downloads.
72	    for (int i = 0; i < 6; ++i) {
73	        faces_[i] = FaceTexture::bake(static_cast<NpcFace>(i));
74	    }
75	
76	    // Atmosphere shader first, so every model loaded below can adopt it.
77	    // Failure (no GL context, GLSL mismatch) degrades to the plain look.
78	    fogShader_ = LoadShaderFromMemory(kFogVertexShader, kFogFragmentShader);
79	    fogLoaded_ = IsShaderValid(fogShader_);
80	    if (fogLoaded_) {
81	        fogCameraLoc_ = GetShaderLocation(fogShader_, "cameraPos");
82	        fogColorLoc_ = GetShaderLocation(fogShader_, "fogColor");
83	        fogLightLoc_ = GetShaderLocation(fogShader_, "lightLevel");
84	        // Daylight defaults; the renderer re-drives fogColor and lightLevel
85	        // each frame from the shared world clock's day/night curves. The
86	        // density is tuned so the plaza (~40 units) stays crisp and the far
87	        // city edge (~150+) visibly hazes.
88	        const float skyColor[4] = {135.f / 255.f, 190.f / 255.f, 235.f / 255.f, 1.f};
89	        const float density = 0.006f;
90	        const float light = 1.f;
91	        SetShaderValue(fogShader_, fogColorLoc_, skyColor, SHADER_UNIFORM_VEC4);
92	        SetShaderValue(fogShader_, GetShaderLocation(fogShader_, "fogDensity"),
93	                       &density, SHADER_UNIFORM_FLOAT);
94	        SetShaderValue(fogShader_, fogLightLoc_, &light, SHADER_UNIFORM_FLOAT);
95	    } else {
96	        std::cerr << "[llm_npc] fog shader failed to compile — plain look\n";
97	    }
